38	public abstract class BaseStrokeContent
39	    implements BaseKeyframeAnimation.AnimationListener, KeyPathElementContent, DrawingContent {
40	
41	  private final PathMeasure pm = new PathMeasure();
42	  private final Path path = new Path();
43	  private final Path trimPathPath = new Path();
44	  private final RectF rect = new RectF();
45	  private final LottieDrawable lottieDrawable;
46	  protected final BaseLayer layer;
47	  private final List<PathGroup> pathGroups = new ArrayList<>();
48	  private final float[] dashPatternValues;
49	  final Paint paint = new LPaint(Paint.ANTI_ALIAS_FLAG);
50	
51	
52	  private final BaseKeyframeAnimation<?, Float> widthAnimation;
53	  private final BaseKeyframeAnimation<?, Integer> opacityAnimation;
54	  private final List<BaseKeyframeAnimation<?, Float>> dashPatternAnimations;
55	  @Nullable private final BaseKeyframeAnimation<?, Float> dashPatternOffsetAnimation;
56	  @Nullable private BaseKeyframeAnimation<ColorFilter, ColorFilter> colorFilterAnimation;
57	  @Nullable private BaseKeyframeAnimation<Float, Float> blurAnimation;
58	  float blurMaskFilterRadius = 0f;
