60	  BaseStrokeContent(final LottieDrawable lottieDrawable, BaseLayer layer, Paint.Cap cap,
61	      Paint.Join join, float miterLimit, AnimatableIntegerValue opacity, AnimatableFloatValue width,
62	      List<AnimatableFloatValue> dashPattern, AnimatableFloatValue offset) {
63	    this.lottieDrawable = lottieDrawable;
64	    this.layer = layer;
65	
66	    paint.setStyle(Paint.Style.STROKE);
67	    paint.setStrokeCap(cap);
68	    paint.setStrokeJoin(join);
69	    paint.setStrokeMiter(miterLimit);
70	
71	    opacityAnimation = opacity.createAnimation();
72	    widthAnimation = width.createAnimation();
73	
74	    if (offset == null) {
75	      dashPatternOffsetAnimation = null;
76	    } else {
77	      dashPatternOffsetAnimation = offset.createAnimation();
78	    }
79	    dashPatternAnimations = new ArrayList<>(dashPattern.size());
80	    dashPatternValues = new float[dashPattern.size()];
81	
82	    for (AnimatableFloatValue dashValue : dashPattern) {
83	      BaseKeyframeAnimation<?, Float> anim = dashValue.createAnimation();
84	      dashPatternAnimations.add(anim);
85	      layer.addAnimation(anim);
86	      anim.addUpdateListener(this);
87	    }
88	
89	    layer.addAnimation(opacityAnimation);
90	    layer.addAnimation(widthAnimation);
91	    if (dashPatternOffsetAnimation != null) {
92	      layer.addAnimation(dashPatternOffsetAnimation);
93	    }
94	
95	    opacityAnimation.addUpdateListener(this);
96	    widthAnimation.addUpdateListener(this);
97	
98	    if (dashPatternOffsetAnimation != null) {
99	      dashPatternOffsetAnimation.addUpdateListener(this);
100	    }
101	
102	    if (layer.getBlurEffect() != null) {
103	      blurAnimation = layer.getBlurEffect().getBlurriness().createAnimation();
104	      blurAnimation.addUpdateListener(this);
105	      layer.addAnimation(blurAnimation);
106	    }
107	  }
108	
109	  @Override public void onValueChanged() {
110	    lottieDrawable.invalidateSelf();
111	  }
112	
113	  @Override public void setContents(List<Content> contentsBefore, List<Content> contentsAfter) {
114	    TrimPathContent trimPathContentBefore = null;
115	    for (int i = contentsBefore.size() - 1; i >= 0; i--) {
116	      Content content = contentsBefore.get(i);
117	      if (content instanceof TrimPathContent &&
118	          ((TrimPathContent) content).getType() == ShapeTrimPath.Type.INDIVIDUALLY) {
119	        trimPathContentBefore = (TrimPathContent) content;
120	      }
121	    }
122	    if (trimPathContentBefore != null) {
123	      trimPathContentBefore.addListener(this);
124	    }
125	
126	    PathGroup currentPathGroup = null;
127	    for (int i = contentsAfter.size() - 1; i >= 0; i--) {
128	      Content content = contentsAfter.get(i);
129	      if (content instanceof TrimPathContent &&
130	          ((TrimPathContent) content).getType() == ShapeTrimPath.Type.INDIVIDUALLY) {
131	        if (currentPathGroup != null) {
132	          pathGroups.add(currentPathGroup);
133	        }
134	        currentPathGroup = new PathGroup((TrimPathContent) content);
135	        ((TrimPathContent) content).addListener(this);
136	      } else if (content instanceof PathContent) {
137	        if (currentPathGroup == null) {
138	          currentPathGroup = new PathGroup(trimPathContentBefore);
139	        }
140	        currentPathGroup.paths.add((PathContent) content);
141	      }
142	    }
143	    if (currentPathGroup != null) {
144	      pathGroups.add(currentPathGroup);
145	    }
146	  }
147	
148	  @Override public void draw(Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow shadowToApply) {
149	    if (L.isTraceEnabled()) {
150	      L.beginSection("StrokeContent#draw");
151	    }
152	    if (Utils.hasZeroScaleAxis(parentMatrix)) {
153	      if (L.isTraceEnabled()) {
154	        L.endSection("StrokeContent#draw");
155	      }
156	      return;
157	    }
158	    float strokeAlpha = opacityAnimation.getValue() / 100f;
159	    int alpha = (int) (parentAlpha * strokeAlpha);
160	    alpha = clamp(alpha, 0, 255);
161	    paint.setAlpha(alpha);
162	    paint.setStrokeWidth(((FloatKeyframeAnimation) widthAnimation).getFloatValue());
163	    if (paint.getStrokeWidth() <= 0) {
164	      // Android draws a hairline stroke for 0, After Effects doesn't.
165	      if (L.isTraceEnabled()) {
166	        L.endSection("StrokeContent#draw");
167	      }
168	      return;
169	    }
170	    applyDashPatternIfNeeded();
171	
172	    if (colorFilterAnimation != null) {
173	      paint.setColorFilter(colorFilterAnimation.getValue());
174	    }
175	
176	    if (blurAnimation != null) {
177	      float blurRadius = blurAnimation.getValue();
178	      if (blurRadius == 0f) {
179	        paint.setMaskFilter(null);
180	      } else if (blurRadius != blurMaskFilterRadius){
181	        BlurMaskFilter blur = layer.getBlurMaskFilter(blurRadius);
182	        paint.setMaskFilter(blur);
183	      }
184	      blurMaskFilterRadius = blurRadius;
185	    }
186	    if (shadowToApply != null) {
187	      shadowToApply.applyWithAlpha((int)(strokeAlpha * 255), paint);
188	    }
189	
190	    canvas.save();
191	    canvas.concat(parentMatrix);
192	    for (PathGroup pathGroup : pathGroups) {
193	
194	
195	      if (pathGroup.trimPath != null) {
196	        applyTrimPath(canvas, pathGroup);
197	      } else {
198	        if (L.isTraceEnabled()) {
199	          L.beginSection("StrokeContent#buildPath");
200	        }
201	        buildPathFromGroup(pathGroup);
202	        if (L.isTraceEnabled()) {
203	          L.endSection("StrokeContent#buildPath");
204	          L.beginSection("StrokeContent#drawPath");
205	        }
206	        canvas.drawPath(path, paint);
207	        if (L.isTraceEnabled()) {
208	          L.endSection("StrokeContent#drawPath");
209	        }
210	      }
211	    }
212	    canvas.restore();
213	    if (L.isTraceEnabled()) {
214	      L.endSection("StrokeContent#draw");
215	    }
216	  }
217	
218	  private void buildPathFromGroup(PathGroup pathGroup) {
219	    path.reset();
220	    for (int j = pathGroup.paths.size() - 1; j >= 0; j--) {
221	      path.addPath(pathGroup.paths.get(j).getPath());
222	    }
223	  }
224	
225	  private void applyTrimPath(Canvas canvas, PathGroup pathGroup) {
226	    if (L.isTraceEnabled()) {
227	      L.beginSection("StrokeContent#applyTrimPath");
228	    }
229	    if (pathGroup.trimPath == null) {
230	      if (L.isTraceEnabled()) {
231	        L.endSection("StrokeContent#applyTrimPath");
232	      }
233	      return;
234	    }
235	    buildPathFromGroup(pathGroup);
236	    float animStartValue = pathGroup.trimPath.getStart().getValue() / 100f;
237	    float animEndValue = pathGroup.trimPath.getEnd().getValue() / 100f;
238	    float animOffsetValue = pathGroup.trimPath.getOffset().getValue() / 360f;
239	
240	    // If the start-end is ~100, consider it to be the full path.
241	    if (animStartValue < 0.01f && animEndValue > 0.99f) {
242	      canvas.drawPath(path, paint);
243	      if (L.isTraceEnabled()) {
244	        L.endSection("StrokeContent#applyTrimPath");
245	      }
246	      return;
247	    }
248	
249	    pm.setPath(path, false);
250	    float totalLength = pm.getLength();
251	    while (pm.nextContour()) {
252	      totalLength += pm.getLength();
253	    }
254	    float offsetLength = totalLength * animOffsetValue;
255	    float startLength = totalLength * animStartValue + offsetLength;
256	    float endLength = Math.min(totalLength * animEndValue + offsetLength, startLength + totalLength - 1f);
257	
258	    float currentLength = 0;
259	    for (int j = pathGroup.paths.size() - 1; j >= 0; j--) {
260	      trimPathPath.set(pathGroup.paths.get(j).getPath());
261	      pm.setPath(trimPathPath, false);
262	      float length = pm.getLength();
263	      if (endLength > totalLength && endLength - totalLength < currentLength + length &&
264	          currentLength < endLength - totalLength) {
265	        // Draw the segment when the end is greater than the length which wraps around to the
266	        // beginning.
267	        float startValue;
268	        if (startLength > totalLength) {
269	          startValue = (startLength - totalLength) / length;
270	        } else {
271	          startValue = 0;
272	        }
273	        float endValue = Math.min((endLength - totalLength) / length, 1);
274	        Utils.applyTrimPathIfNeeded(trimPathPath, startValue, endValue, 0);
275	        canvas.drawPath(trimPathPath, paint);
276	      } else
277	        //noinspection StatementWithEmptyBody
278	        if (currentLength + length < startLength || currentLength > endLength) {
279	          // Do nothing
280	        } else if (currentLength + length <= endLength && startLength < currentLength) {
281	          canvas.drawPath(trimPathPath, paint);
282	        } else {
283	          float startValue;
284	          if (startLength < currentLength) {
285	            startValue = 0;
286	          } else {
287	            startValue = (startLength - currentLength) / length;
288	          }
289	          float endValue;
290	          if (endLength > currentLength + length) {
291	            endValue = 1f;
292	          } else {
293	            endValue = (endLength - currentLength) / length;
294	          }
295	          Utils.applyTrimPathIfNeeded(trimPathPath, startValue, endValue, 0);
296	          canvas.drawPath(trimPathPath, paint);
297	        }
298	      currentLength += length;
299	    }
300	    if (L.isTraceEnabled()) {
301	      L.endSection("StrokeContent#applyTrimPath");
302	    }
303	  }
304	
305	  @Override public void getBounds(RectF outBounds, Matrix parentMatrix, boolean applyParents) {
306	    if (L.isTraceEnabled()) {
307	      L.beginSection("StrokeContent#getBounds");
308	    }
309	    path.reset();
310	    for (PathGroup pathGroup : pathGroups) {
311	      for (PathContent pathContent : pathGroup.paths) {
312	        path.addPath(pathContent.getPath(), parentMatrix);
313	      }
314	    }
315	    path.computeBounds(rect, false);
316	
317	    float width = ((FloatKeyframeAnimation) widthAnimation).getFloatValue();
318	    float halfWidth = width / 2f;
319	    outBounds.set(rect.left - halfWidth - 1, rect.top - halfWidth - 1,
320	        rect.right + halfWidth + 1, rect.bottom + halfWidth + 1);
321	    if (L.isTraceEnabled()) {
322	      L.endSection("StrokeContent#getBounds");
323	    }
324	  }
325	
326	  private void applyDashPatternIfNeeded() {
327	    if (L.isTraceEnabled()) {
328	      L.beginSection("StrokeContent#applyDashPattern");
329	    }
330	    if (dashPatternAnimations.isEmpty()) {
331	      if (L.isTraceEnabled()) {
332	        L.endSection("StrokeContent#applyDashPattern");
333	      }
334	      return;
335	    }
336	
337	    for (int i = 0; i < dashPatternAnimations.size(); i++) {
338	      dashPatternValues[i] = dashPatternAnimations.get(i).getValue();
339	      // If the value of the dash pattern or gap is too small, the number of individual sections
340	      // approaches infinity as the value approaches 0.
341	      // To mitigate this, we essentially put a minimum value on the dash pattern size of 1px
342	      // and a minimum gap size of 0.01.
343	      if (i % 2 == 0) {
344	        if (dashPatternValues[i] < 1f) {
345	          dashPatternValues[i] = 1f;
346	        }
347	      } else {
348	        if (dashPatternValues[i] < 0.1f) {
349	          dashPatternValues[i] = 0.1f;
350	        }
351	      }
352	    }
353	    float offset = dashPatternOffsetAnimation == null ? 0f : dashPatternOffsetAnimation.getValue();
354	    paint.setPathEffect(new DashPathEffect(dashPatternValues, offset));
355	    if (L.isTraceEnabled()) {
356	      L.endSection("StrokeContent#applyDashPattern");
357	    }
358	  }
359	
360	  @Override public void resolveKeyPath(
361	      KeyPath keyPath, int depth, List<KeyPath> accumulator, KeyPath currentPartialKeyPath) {
362	    MiscUtils.resolveKeyPath(keyPath, depth, accumulator, currentPartialKeyPath, this);
363	  }
364	
365	  @SuppressWarnings("unchecked")
366	  @Override
367	  @CallSuper
368	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
369	    if (property == LottieProperty.OPACITY) {
370	      opacityAnimation.setValueCallback((LottieValueCallback<Integer>) callback);
371	    } else if (property == LottieProperty.STROKE_WIDTH) {
372	      widthAnimation.setValueCallback((LottieValueCallback<Float>) callback);
373	    } else if (property == LottieProperty.COLOR_FILTER) {
374	      if (colorFilterAnimation != null) {
375	        layer.removeAnimation(colorFilterAnimation);
376	      }
377	
378	      if (callback == null) {
379	        colorFilterAnimation = null;
380	      } else {
381	        colorFilterAnimation =
382	            new ValueCallbackKeyframeAnimation<>((LottieValueCallback<ColorFilter>) callback);
383	        colorFilterAnimation.addUpdateListener(this);
384	        layer.addAnimation(colorFilterAnimation);
385	      }
386	    } else if (property == LottieProperty.BLUR_RADIUS) {
387	      if (blurAnimation != null) {
388	        blurAnimation.setValueCallback((LottieValueCallback<Float>) callback);
389	      } else {
390	        blurAnimation =
391	            new ValueCallbackKeyframeAnimation<>((LottieValueCallback<Float>) callback);
392	        blurAnimation.addUpdateListener(this);
393	        layer.addAnimation(blurAnimation);
394	      }
395	    }
396	  }
