399	   * Data class to help drawing trim paths individually.
400	   */
401	  private static final class PathGroup {
402	    private final List<PathContent> paths = new ArrayList<>();
403	    @Nullable private final TrimPathContent trimPath;
404	
405	    private PathGroup(@Nullable TrimPathContent trimPath) {
406	      this.trimPath = trimPath;
407	    }
408	  }
