34	  private static List<Content> contentsFromModels(LottieDrawable drawable, LottieComposition composition, BaseLayer layer,
35	      List<ContentModel> contentModels) {
36	    List<Content> contents = new ArrayList<>(contentModels.size());
37	    for (ContentModel model : contentModels) {
38	      Content content = model.toContent(drawable, composition, layer);
39	      if (content != null) {
40	        contents.add(content);
41	      }
42	    }
43	    return contents;
44	  }
