46	  @Nullable static AnimatableTransform findTransform(List<ContentModel> contentModels) {
47	    for (ContentModel contentModel : contentModels) {
48	      if (contentModel instanceof AnimatableTransform) {
49	        return (AnimatableTransform) contentModel;
50	      }
51	    }
52	    return null;
53	  }
