55	  private final Matrix matrix = new Matrix();
56	  private final Path path = new Path();
57	  private final RectF rect = new RectF();
58	
59	  private final String name;
60	  private final boolean hidden;
61	  private final List<Content> contents;
62	  private final LottieDrawable lottieDrawable;
63	  @Nullable private List<PathContent> pathContents;
64	  @Nullable private TransformKeyframeAnimation transformAnimation;
