66	  public ContentGroup(final LottieDrawable lottieDrawable, BaseLayer layer, ShapeGroup shapeGroup, LottieComposition composition) {
67	    this(lottieDrawable, layer, shapeGroup.getName(),
68	        shapeGroup.isHidden(), contentsFromModels(lottieDrawable, composition, layer, shapeGroup.getItems()),
69	        findTransform(shapeGroup.getItems()));
70	  }
71	
72	  ContentGroup(final LottieDrawable lottieDrawable, BaseLayer layer,
73	      String name, boolean hidden, List<Content> contents, @Nullable AnimatableTransform transform) {
74	    this.name = name;
75	    this.lottieDrawable = lottieDrawable;
76	    this.hidden = hidden;
77	    this.contents = contents;
78	
79	    if (transform != null) {
80	      transformAnimation = transform.createAnimation();
81	      transformAnimation.addAnimationsToLayer(layer);
82	      transformAnimation.addListener(this);
83	    }
84	
85	    List<GreedyContent> greedyContents = new ArrayList<>();
86	    for (int i = contents.size() - 1; i >= 0; i--) {
87	      Content content = contents.get(i);
88	      if (content instanceof GreedyContent) {
89	        greedyContents.add((GreedyContent) content);
90	      }
91	    }
92	
93	    for (int i = greedyContents.size() - 1; i >= 0; i--) {
94	      greedyContents.get(i).absorbContent(contents.listIterator(contents.size()));
95	    }
96	  }
