106	  @Override public void setContents(List<Content> contentsBefore, List<Content> contentsAfter) {
107	    // Do nothing with contents after.
108	    List<Content> myContentsBefore = new ArrayList<>(contentsBefore.size() + contents.size());
109	    myContentsBefore.addAll(contentsBefore);
110	
111	    for (int i = contents.size() - 1; i >= 0; i--) {
112	      Content content = contents.get(i);
113	      content.setContents(myContentsBefore, contents.subList(0, i));
114	      myContentsBefore.add(content);
115	    }
116	  }
