142	  @Override public Path getPath() {
143	    // TODO: cache this somehow.
144	    matrix.reset();
145	    if (transformAnimation != null) {
146	      matrix.set(transformAnimation.getMatrix());
147	    }
148	    path.reset();
149	    if (hidden) {
150	      return path;
151	    }
152	    for (int i = contents.size() - 1; i >= 0; i--) {
153	      Content content = contents.get(i);
154	      if (content instanceof PathContent) {
155	        path.addPath(((PathContent) content).getPath(), matrix);
156	      }
157	    }
158	    return path;
159	  }
