161	  @Override public void draw(Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow shadowToApply) {
162	    if (hidden) {
163	      return;
164	    }
165	    matrix.set(parentMatrix);
166	    int layerAlpha;
167	    if (transformAnimation != null) {
168	      matrix.preConcat(transformAnimation.getMatrix());
169	      int opacity = transformAnimation.getOpacity() == null ? 100 : transformAnimation.getOpacity().getValue();
170	      layerAlpha = (int) ((opacity / 100f * parentAlpha / 255f) * 255);
171	    } else {
172	      layerAlpha = parentAlpha;
173	    }
174	
175	    // Apply off-screen rendering only when needed in order to improve rendering performance.
176	    boolean isRenderingWithOffScreen =
177	        (lottieDrawable.isApplyingOpacityToLayersEnabled() && hasTwoOrMoreDrawableContent() && layerAlpha != 255) ||
178	        (shadowToApply != null && lottieDrawable.isApplyingShadowToLayersEnabled() && hasTwoOrMoreDrawableContent());
179	    int childAlpha = isRenderingWithOffScreen ? 255 : layerAlpha;
180	
181	    Canvas contentCanvas = canvas;
182	    if (isRenderingWithOffScreen) {
183	      offScreenRectF.set(0, 0, 0, 0);
184	      getBounds(offScreenRectF, parentMatrix, true);
185	      offscreenOp.alpha = layerAlpha;
186	      if (shadowToApply != null) {
187	        shadowToApply.applyTo(offscreenOp);
188	        shadowToApply = null; // Don't pass it to children - OffscreenLayer now takes care of this
189	      } else {
190	        offscreenOp.shadow = null;
191	      }
192	
193	      contentCanvas = offscreenLayer.start(canvas, offScreenRectF, offscreenOp);
194	    } else {
195	      if (shadowToApply != null) {
196	        shadowToApply = new DropShadow(shadowToApply);
197	        shadowToApply.multiplyOpacity(childAlpha);
198	      }
199	    }
200	
201	    for (int i = contents.size() - 1; i >= 0; i--) {
202	      Object content = contents.get(i);
203	      if (content instanceof DrawingContent) {
204	        ((DrawingContent) content).draw(contentCanvas, matrix, childAlpha, shadowToApply);
205	      }
206	    }
207	
208	    if (isRenderingWithOffScreen) {
209	      offscreenLayer.finish();
210	    }
211	  }
