213	  private boolean hasTwoOrMoreDrawableContent() {
214	    int drawableContentCount = 0;
215	    for (Content content : contents) {
216	      if (content instanceof DrawingContent) {
217	        drawableContentCount += 1;
218	        if (drawableContentCount >= 2) {
219	          return true;
220	        }
221	      }
222	    }
223	    return false;
224	  }
