226	  @Override public void getBounds(RectF outBounds, Matrix parentMatrix, boolean applyParents) {
227	    matrix.set(parentMatrix);
228	    if (transformAnimation != null) {
229	      matrix.preConcat(transformAnimation.getMatrix());
230	    }
231	    rect.set(0, 0, 0, 0);
232	    for (int i = contents.size() - 1; i >= 0; i--) {
233	      Content content = contents.get(i);
234	      if (content instanceof DrawingContent) {
235	        ((DrawingContent) content).getBounds(rect, matrix, applyParents);
236	        outBounds.union(rect);
237	      }
238	    }
239	  }
