241	  @Override public void resolveKeyPath(
242	      KeyPath keyPath, int depth, List<KeyPath> accumulator, KeyPath currentPartialKeyPath) {
243	    if (!keyPath.matches(getName(), depth) && !"__container".equals(getName())) {
244	      return;
245	    }
246	
247	    if (!"__container".equals(getName())) {
248	      currentPartialKeyPath = currentPartialKeyPath.addKey(getName());
249	
250	      if (keyPath.fullyResolvesTo(getName(), depth)) {
251	        accumulator.add(currentPartialKeyPath.resolve(this));
252	      }
253	    }
254	
255	    if (keyPath.propagateToChildren(getName(), depth)) {
256	      int newDepth = depth + keyPath.incrementDepthBy(getName(), depth);
257	      for (Content content : contents) {
258	        if (content instanceof KeyPathElement) {
259	          ((KeyPathElement) content).resolveKeyPath(keyPath, newDepth, accumulator, currentPartialKeyPath);
260	        }
261	      }
262	    }
263	  }
