234	  @Override
235	  public void draw(Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow shadowToApply) {
236	    L.beginSection(drawTraceName);
237	    if (!visible || layerModel.isHidden()) {
238	      L.endSection(drawTraceName);
239	      return;
240	    }
241	    buildParentLayerListIfNeeded();
242	    if (L.isTraceEnabled()) {
243	      L.beginSection("Layer#parentMatrix");
244	    }
245	    matrix.reset();
246	    matrix.set(parentMatrix);
247	    for (int i = parentLayers.size() - 1; i >= 0; i--) {
248	      matrix.preConcat(parentLayers.get(i).transform.getMatrix());
249	    }
250	    if (L.isTraceEnabled()) {
251	      L.endSection("Layer#parentMatrix");
252	    }
253	    // It is unclear why but getting the opacity here would sometimes NPE.
254	    // The extra code here is designed to avoid this.
255	    // https://github.com/airbnb/lottie-android/issues/2083
256	    int opacity = 100;
257	    BaseKeyframeAnimation<?, Integer> opacityAnimation = transform.getOpacity();
258	    if (opacityAnimation != null) {
259	      Integer opacityValue = opacityAnimation.getValue();
260	      if (opacityValue != null) {
261	        opacity = opacityValue;
262	      }
263	    }
264	    int alpha = (int) ((parentAlpha / 255f * (float) opacity / 100f) * 255);
265	    if (!hasMatteOnThisLayer() && !hasMasksOnThisLayer() && getBlendMode() == LBlendMode.NORMAL) {
266	      matrix.preConcat(transform.getMatrix());
267	      if (L.isTraceEnabled()) {
268	        L.beginSection("Layer#drawLayer");
269	      }
270	      drawLayer(canvas, matrix, alpha, shadowToApply);
271	      if (L.isTraceEnabled()) {
272	        L.endSection("Layer#drawLayer");
273	      }
274	      recordRenderTime(L.endSection(drawTraceName));
275	      return;
276	    }
277	
278	    if (L.isTraceEnabled()) {
279	      L.beginSection("Layer#computeBounds");
280	    }
281	    getBounds(rect, matrix, false);
282	
283	    intersectBoundsWithMatte(rect, parentMatrix);
284	
285	    matrix.preConcat(transform.getMatrix());
286	    intersectBoundsWithMask(rect, matrix);
287	
288	    // Intersect the mask and matte rect with the canvas bounds.
289	    // If the canvas has a transform, then we need to transform its bounds by its matrix
290	    // so that we know the coordinate space that the canvas is showing.
291	    canvasBounds.set(0f, 0f, canvas.getWidth(), canvas.getHeight());
292	    //noinspection deprecation
293	    canvas.getMatrix(canvasMatrix);
294	    if (!canvasMatrix.isIdentity()) {
295	      canvasMatrix.invert(canvasMatrix);
296	      canvasMatrix.mapRect(canvasBounds);
297	    }
298	    if (!rect.intersect(canvasBounds)) {
299	      rect.set(0, 0, 0, 0);
300	    }
301	
302	    if (L.isTraceEnabled()) {
303	      L.endSection("Layer#computeBounds");
304	    }
305	
306	    // Ensure that what we are drawing is >=1px of width and height.
307	    // On older devices, drawing to an offscreen buffer of <1px would draw back as a black bar.
308	    // https://github.com/airbnb/lottie-android/issues/1625
309	    if (rect.width() >= 1f && rect.height() >= 1f) {
310	      if (L.isTraceEnabled()) {
311	        L.beginSection("Layer#saveLayer");
312	      }
313	      contentPaint.setAlpha(255);
314	      PaintCompat.setBlendMode(contentPaint, getBlendMode().toNativeBlendMode());
315	
316	      Utils.saveLayerCompat(canvas, rect, contentPaint);
317	      if (L.isTraceEnabled()) {
318	        L.endSection("Layer#saveLayer");
319	      }
320	
321	      // Clear the off screen buffer. This is necessary for some phones.
322	      if (getBlendMode() != LBlendMode.MULTIPLY) {
323	        clearCanvas(canvas);
324	      } else {
325	        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) {
326	          // Due to the difference between PorterDuffMode.MODULATE (which we use for compatibility
327	          // with Android < Q) and BlendMode.MULTIPLY (which is the correct, alpha-blended mode),
328	          // we will alpha-blend the contents of this layer on top of a white background before
329	          // we multiply it with the opaque substrate below (with canvas.restore()).
330	          //
331	          // Since white is the identity color for multiplication, this will behave as if we
332	          // had correctly performed an alpha-blended multiply (such as BlendMode.MULTIPLY), but
333	          // will work pre-Q as well.
334	          if (solidWhitePaint == null) {
335	            solidWhitePaint = new LPaint();
336	            solidWhitePaint.setColor(0xffffffff);
337	          }
338	          canvas.drawRect(rect.left - 1, rect.top - 1, rect.right + 1, rect.bottom + 1, solidWhitePaint);
339	        }
340	      }
341	
342	      if (L.isTraceEnabled()) {
343	        L.beginSection("Layer#drawLayer");
344	      }
345	      drawLayer(canvas, matrix, alpha, shadowToApply);
346	      if (L.isTraceEnabled()) {
347	        L.endSection("Layer#drawLayer");
348	      }
349	
350	      if (hasMasksOnThisLayer()) {
351	        applyMasks(canvas, matrix);
352	      }
353	
354	      if (hasMatteOnThisLayer()) {
355	        if (L.isTraceEnabled()) {
356	          L.beginSection("Layer#drawMatte");
357	          L.beginSection("Layer#saveLayer");
358	        }
359	        Utils.saveLayerCompat(canvas, rect, mattePaint, SAVE_FLAGS);
360	        if (L.isTraceEnabled()) {
361	          L.endSection("Layer#saveLayer");
362	        }
363	        clearCanvas(canvas);
364	        //noinspection ConstantConditions
365	        matteLayer.draw(canvas, parentMatrix, parentAlpha, null);
366	        if (L.isTraceEnabled()) {
367	          L.beginSection("Layer#restoreLayer");
368	        }
369	        canvas.restore();
370	        if (L.isTraceEnabled()) {
371	          L.endSection("Layer#restoreLayer");
372	          L.endSection("Layer#drawMatte");
373	        }
374	      }
375	
376	      if (L.isTraceEnabled()) {
377	        L.beginSection("Layer#restoreLayer");
378	      }
379	      canvas.restore();
380	      if (L.isTraceEnabled()) {
381	        L.endSection("Layer#restoreLayer");
382	      }
383	    }
384	
385	    if (outlineMasksAndMattes && outlineMasksAndMattesPaint != null) {
386	      outlineMasksAndMattesPaint.setStyle(Paint.Style.STROKE);
387	      outlineMasksAndMattesPaint.setColor(0xFFFC2803);
388	      outlineMasksAndMattesPaint.setStrokeWidth(4);
389	      canvas.drawRect(rect, outlineMasksAndMattesPaint);
390	      outlineMasksAndMattesPaint.setStyle(Paint.Style.FILL);
391	      outlineMasksAndMattesPaint.setColor(0x50EBEBEB);
392	      canvas.drawRect(rect, outlineMasksAndMattesPaint);
393	    }
394	
395	    recordRenderTime(L.endSection(drawTraceName));
396	  }
