415	  private void intersectBoundsWithMask(RectF rect, Matrix matrix) {
416	    maskBoundsRect.set(0, 0, 0, 0);
417	    if (!hasMasksOnThisLayer()) {
418	      return;
419	    }
420	    //noinspection ConstantConditions
421	    int size = mask.getMasks().size();
422	    for (int i = 0; i < size; i++) {
423	      Mask mask = this.mask.getMasks().get(i);
424	      BaseKeyframeAnimation<?, Path> maskAnimation = this.mask.getMaskAnimations().get(i);
425	      Path maskPath = maskAnimation.getValue();
426	      if (maskPath == null) {
427	        // This should never happen but seems to happen occasionally.
428	        // There is no known repro for this but is is probably best to just skip this mask if that is the case.
429	        // https://github.com/airbnb/lottie-android/issues/1879
430	        continue;
431	      }
432	      path.set(maskPath);
433	      path.transform(matrix);
434	
435	      switch (mask.getMaskMode()) {
436	        case MASK_MODE_NONE:
437	          // Mask mode none will just render the original content so it is the whole bounds.
438	          return;
439	        case MASK_MODE_SUBTRACT:
440	          // If there is a subtract mask, the mask could potentially be the size of the entire
441	          // canvas so we can't use the mask bounds.
442	          return;
443	        case MASK_MODE_INTERSECT:
444	        case MASK_MODE_ADD:
445	          if (mask.isInverted()) {
446	            return;
447	          }
448	        default:
449	          path.computeBounds(tempMaskBoundsRect, false);
450	          // As we iterate through the masks, we want to calculate the union region of the masks.
451	          // We initialize the rect with the first mask. If we don't call set() on the first call,
452	          // the rect will always extend to (0,0).
453	          if (i == 0) {
454	            maskBoundsRect.set(tempMaskBoundsRect);
455	          } else {
456	            maskBoundsRect.union(tempMaskBoundsRect);
457	          }
458	      }
459	    }
460	
461	    if (!rect.intersect(maskBoundsRect)) {
462	      rect.set(0f, 0f, 0f, 0f);
463	    }
464	  }
465	
466	  private void intersectBoundsWithMatte(RectF rect, Matrix matrix) {
467	    if (!hasMatteOnThisLayer()) {
468	      return;
469	    }
470	
471	    if (layerModel.getMatteType() == Layer.MatteType.INVERT) {
472	      // We can't trim the bounds if the mask is inverted since it extends all the way to the
473	      // composition bounds.
474	      return;
475	    }
476	    matteBoundsRect.set(0f, 0f, 0f, 0f);
477	    matteLayer.getBounds(matteBoundsRect, matrix, true);
478	    if (!rect.intersect(matteBoundsRect)) {
479	      rect.set(0f, 0f, 0f, 0f);
480	    }
481	  }
