483	  abstract void drawLayer(Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow shadowToApply);
484	
485	  private void applyMasks(Canvas canvas, Matrix matrix) {
486	    if (L.isTraceEnabled()) {
487	      L.beginSection("Layer#saveLayer");
488	    }
489	    Utils.saveLayerCompat(canvas, rect, dstInPaint, SAVE_FLAGS);
490	    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.P) {
491	      // Pre-Pie, offscreen buffers were opaque which meant that outer border of a mask
492	      // might get drawn depending on the result of float rounding.
493	      clearCanvas(canvas);
494	    }
495	    if (L.isTraceEnabled()) {
496	      L.endSection("Layer#saveLayer");
497	    }
498	    for (int i = 0; i < mask.getMasks().size(); i++) {
499	      Mask mask = this.mask.getMasks().get(i);
500	      BaseKeyframeAnimation<ShapeData, Path> maskAnimation = this.mask.getMaskAnimations().get(i);
501	      BaseKeyframeAnimation<Integer, Integer> opacityAnimation = this.mask.getOpacityAnimations().get(i);
502	      switch (mask.getMaskMode()) {
503	        case MASK_MODE_NONE:
504	          // None mask should have no effect. If all masks are NONE, fill the
505	          // mask canvas with a rectangle so it fully covers the original layer content.
506	          // However, if there are other masks, they should be the only ones that have an effect so
507	          // this should noop.
508	          if (areAllMasksNone()) {
509	            contentPaint.setAlpha(255);
510	            canvas.drawRect(rect, contentPaint);
511	          }
512	          break;
513	        case MASK_MODE_ADD:
514	          if (mask.isInverted()) {
515	            applyInvertedAddMask(canvas, matrix, maskAnimation, opacityAnimation);
516	          } else {
517	            applyAddMask(canvas, matrix, maskAnimation, opacityAnimation);
518	          }
519	          break;
520	        case MASK_MODE_SUBTRACT:
521	          if (i == 0) {
522	            contentPaint.setColor(Color.BLACK);
523	            contentPaint.setAlpha(255);
524	            canvas.drawRect(rect, contentPaint);
525	          }
526	          if (mask.isInverted()) {
527	            applyInvertedSubtractMask(canvas, matrix, maskAnimation, opacityAnimation);
528	          } else {
529	            applySubtractMask(canvas, matrix, maskAnimation);
530	          }
531	          break;
532	        case MASK_MODE_INTERSECT:
