738	  public void resolveKeyPath(
739	      KeyPath keyPath, int depth, List<KeyPath> accumulator, KeyPath currentPartialKeyPath) {
740	    if (matteLayer != null) {
741	      KeyPath matteCurrentPartialKeyPath = currentPartialKeyPath.addKey(matteLayer.getName());
742	      if (keyPath.fullyResolvesTo(matteLayer.getName(), depth)) {
743	        accumulator.add(matteCurrentPartialKeyPath.resolve(matteLayer));
744	      }
745	
746	      if (keyPath.matches(matteLayer.getName(), depth) && keyPath.propagateToChildren(getName(), depth)) {
747	        int newDepth = depth + keyPath.incrementDepthBy(matteLayer.getName(), depth);
748	        matteLayer.resolveChildKeyPath(keyPath, newDepth, accumulator, matteCurrentPartialKeyPath);
749	      }
750	    }
751	
752	    if (!keyPath.matches(getName(), depth)) {
753	      return;
754	    }
755	
756	    if (!"__container".equals(getName())) {
757	      currentPartialKeyPath = currentPartialKeyPath.addKey(getName());
758	
759	      if (keyPath.fullyResolvesTo(getName(), depth)) {
760	        accumulator.add(currentPartialKeyPath.resolve(this));
761	      }
762	    }
763	
764	    if (keyPath.propagateToChildren(getName(), depth)) {
765	      int newDepth = depth + keyPath.incrementDepthBy(getName(), depth);
766	      resolveChildKeyPath(keyPath, newDepth, accumulator, currentPartialKeyPath);
767	    }
768	  }
