42	  /**
43	   * Cache the gradients such that it runs at 30fps.
44	   */
45	  private static final int CACHE_STEPS_MS = 32;
46	  @NonNull private final String name;
47	  private final boolean hidden;
48	  private final BaseLayer layer;
49	  private final LongSparseArray<LinearGradient> linearGradientCache = new LongSparseArray<>();
50	  private final LongSparseArray<RadialGradient> radialGradientCache = new LongSparseArray<>();
51	  private final Path path = new Path();
52	  private final Paint paint = new LPaint(Paint.ANTI_ALIAS_FLAG);
53	  private final RectF boundsRect = new RectF();
54	  private final List<PathContent> paths = new ArrayList<>();
55	  private final GradientType type;
56	  private final BaseKeyframeAnimation<GradientColor, GradientColor> colorAnimation;
57	  private final BaseKeyframeAnimation<Integer, Integer> opacityAnimation;
58	  private final BaseKeyframeAnimation<PointF, PointF> startPointAnimation;
59	  private final BaseKeyframeAnimation<PointF, PointF> endPointAnimation;
60	  @Nullable private BaseKeyframeAnimation<ColorFilter, ColorFilter> colorFilterAnimation;
61	  @Nullable private ValueCallbackKeyframeAnimation colorCallbackAnimation;
62	  private final LottieDrawable lottieDrawable;
63	  private final int cacheSteps;
64	  @Nullable private BaseKeyframeAnimation<Float, Float> blurAnimation;
65	  float blurMaskFilterRadius = 0f;
