67	  public GradientFillContent(final LottieDrawable lottieDrawable, LottieComposition composition, BaseLayer layer, GradientFill fill) {
68	    this.layer = layer;
69	    name = fill.getName();
70	    hidden = fill.isHidden();
71	    this.lottieDrawable = lottieDrawable;
72	    type = fill.getGradientType();
73	    path.setFillType(fill.getFillType());
74	    cacheSteps = (int) (composition.getDuration() / CACHE_STEPS_MS);
75	
76	    colorAnimation = fill.getGradientColor().createAnimation();
77	    colorAnimation.addUpdateListener(this);
78	    layer.addAnimation(colorAnimation);
79	
80	    opacityAnimation = fill.getOpacity().createAnimation();
81	    opacityAnimation.addUpdateListener(this);
82	    layer.addAnimation(opacityAnimation);
83	
84	    startPointAnimation = fill.getStartPoint().createAnimation();
85	    startPointAnimation.addUpdateListener(this);
86	    layer.addAnimation(startPointAnimation);
87	
88	    endPointAnimation = fill.getEndPoint().createAnimation();
89	    endPointAnimation.addUpdateListener(this);
90	    layer.addAnimation(endPointAnimation);
91	
92	    if (layer.getBlurEffect() != null) {
93	      blurAnimation = layer.getBlurEffect().getBlurriness().createAnimation();
94	      blurAnimation.addUpdateListener(this);
95	      layer.addAnimation(blurAnimation);
96	    }
97	  }
