111	  @Override public void draw(Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow shadowToApply) {
112	    if (hidden) {
113	      return;
114	    }
115	    if (L.isTraceEnabled()) {
116	      L.beginSection("GradientFillContent#draw");
117	    }
118	    path.reset();
119	    for (PathContent p : paths) {
120	      path.addPath(p.getPath(), parentMatrix);
121	    }
122	
123	    path.computeBounds(boundsRect, false);
124	
125	    Shader shader;
126	    if (type == GradientType.LINEAR) {
127	      shader = getLinearGradient();
128	    } else {
129	      shader = getRadialGradient();
130	    }
131	    shader.setLocalMatrix(parentMatrix);
132	    paint.setShader(shader);
133	
134	    if (colorFilterAnimation != null) {
135	      paint.setColorFilter(colorFilterAnimation.getValue());
136	    }
137	
138	    if (blurAnimation != null) {
139	      float blurRadius = blurAnimation.getValue();
140	      if (blurRadius == 0f) {
141	        paint.setMaskFilter(null);
142	      } else if (blurRadius != blurMaskFilterRadius){
143	        BlurMaskFilter blur = new BlurMaskFilter(blurRadius, BlurMaskFilter.Blur.NORMAL);
144	        paint.setMaskFilter(blur);
145	      }
146	      blurMaskFilterRadius = blurRadius;
147	    }
148	
149	    float fillAlpha = opacityAnimation.getValue() / 100f;
150	    int alpha = (int) (parentAlpha * fillAlpha);
151	    alpha = clamp(alpha, 0, 255);
152	    paint.setAlpha(alpha);
153	
154	    if (shadowToApply != null) {
155	      shadowToApply.applyWithAlpha((int)(fillAlpha * 255), paint);
156	    }
157	
158	    canvas.drawPath(path, paint);
159	    if (L.isTraceEnabled()) {
160	      L.endSection("GradientFillContent#draw");
161	    }
162	  }
