179	  private LinearGradient getLinearGradient() {
180	    int gradientHash = getGradientHash();
181	    LinearGradient gradient = linearGradientCache.get(gradientHash);
182	    if (gradient != null) {
183	      return gradient;
184	    }
185	    PointF startPoint = startPointAnimation.getValue();
186	    PointF endPoint = endPointAnimation.getValue();
187	    GradientColor gradientColor = colorAnimation.getValue();
188	    int[] colors = applyDynamicColorsIfNeeded(gradientColor.getColors());
189	    float[] positions = gradientColor.getPositions();
190	
191	    if (colors.length < 2) {
192	      colors = new int[]{colors[0], colors[0]};
193	      positions = new float[]{0f, 1f};
194	    }
195	    gradient = new LinearGradient(startPoint.x, startPoint.y, endPoint.x, endPoint.y, colors,
196	        positions, Shader.TileMode.CLAMP);
197	    linearGradientCache.put(gradientHash, gradient);
198	    return gradient;
199	  }
200	
201	  private RadialGradient getRadialGradient() {
202	    int gradientHash = getGradientHash();
203	    RadialGradient gradient = radialGradientCache.get(gradientHash);
204	    if (gradient != null) {
205	      return gradient;
206	    }
207	    PointF startPoint = startPointAnimation.getValue();
208	    PointF endPoint = endPointAnimation.getValue();
209	    GradientColor gradientColor = colorAnimation.getValue();
210	    int[] colors = applyDynamicColorsIfNeeded(gradientColor.getColors());
211	    float[] positions = gradientColor.getPositions();
212	    if (colors.length < 2) {
213	      colors = new int[]{colors[0], colors[0]};
214	      positions = new float[]{0f, 1f};
215	    }
216	    float x0 = startPoint.x;
217	    float y0 = startPoint.y;
218	    float x1 = endPoint.x;
219	    float y1 = endPoint.y;
220	    float r = (float) Math.hypot(x1 - x0, y1 - y0);
221	    if (r <= 0) {
222	      r = 0.001f;
223	    }
224	    gradient = new RadialGradient(x0, y0, r, colors, positions, Shader.TileMode.CLAMP);
225	    radialGradientCache.put(gradientHash, gradient);
226	    return gradient;
227	  }
228	
229	  private int getGradientHash() {
230	    int startPointProgress = Math.round(startPointAnimation.getProgress() * cacheSteps);
231	    int endPointProgress = Math.round(endPointAnimation.getProgress() * cacheSteps);
232	    int colorProgress = Math.round(colorAnimation.getProgress() * cacheSteps);
233	    int hash = 17;
234	    if (startPointProgress != 0) {
235	      hash = hash * 31 * startPointProgress;
236	    }
237	    if (endPointProgress != 0) {
238	      hash = hash * 31 * endPointProgress;
239	    }
240	    if (colorProgress != 0) {
241	      hash = hash * 31 * colorProgress;
242	    }
243	    return hash;
244	  }
245	
246	  private int[] applyDynamicColorsIfNeeded(int[] colors) {
247	    if (colorCallbackAnimation == null) {
248	      return colors;
249	    }
250	    Integer[] dynamicColors = (Integer[]) colorCallbackAnimation.getValue();
251	    int[] result = colors.length == dynamicColors.length ? colors : new int[dynamicColors.length];
252	    for (int i = 0; i < dynamicColors.length; i++) {
253	      result[i] = dynamicColors[i];
254	    }
255	    return result;
256	  }
