258	  @Override public void resolveKeyPath(
259	      KeyPath keyPath, int depth, List<KeyPath> accumulator, KeyPath currentPartialKeyPath) {
260	    MiscUtils.resolveKeyPath(keyPath, depth, accumulator, currentPartialKeyPath, this);
261	  }
