263	  @SuppressWarnings("unchecked")
264	  @Override
265	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
266	    if (property == LottieProperty.OPACITY) {
267	      opacityAnimation.setValueCallback((LottieValueCallback<Integer>) callback);
268	    } else if (property == LottieProperty.COLOR_FILTER) {
269	      if (colorFilterAnimation != null) {
270	        layer.removeAnimation(colorFilterAnimation);
271	      }
272	
273	      if (callback == null) {
274	        colorFilterAnimation = null;
275	      } else {
276	        colorFilterAnimation =
277	            new ValueCallbackKeyframeAnimation<>((LottieValueCallback<ColorFilter>) callback);
278	        colorFilterAnimation.addUpdateListener(this);
279	        layer.addAnimation(colorFilterAnimation);
280	      }
281	    } else if (property == LottieProperty.GRADIENT_COLOR) {
282	      if (colorCallbackAnimation != null) {
283	        layer.removeAnimation(colorCallbackAnimation);
284	      }
285	
286	      if (callback == null) {
287	        colorCallbackAnimation = null;
288	      } else {
289	        linearGradientCache.clear();
290	        radialGradientCache.clear();
291	        colorCallbackAnimation = new ValueCallbackKeyframeAnimation<>(callback);
292	        colorCallbackAnimation.addUpdateListener(this);
293	        layer.addAnimation(colorCallbackAnimation);
294	      }
295	    } else if (property == LottieProperty.BLUR_RADIUS) {
296	      if (blurAnimation != null) {
297	        blurAnimation.setValueCallback((LottieValueCallback<Float>) callback);
298	      } else {
299	        blurAnimation =
300	            new ValueCallbackKeyframeAnimation<>((LottieValueCallback<Float>) callback);
301	        blurAnimation.addUpdateListener(this);
302	        layer.addAnimation(blurAnimation);
303	      }
304	    }
305	  }
