61	    layer.addAnimation(startPointAnimation);
62	
63	    endPointAnimation = stroke.getEndPoint().createAnimation();
64	    endPointAnimation.addUpdateListener(this);
65	    layer.addAnimation(endPointAnimation);
66	  }
