68	  @Override public void draw(Canvas canvas, Matrix parentMatrix, int parentAlpha, DropShadow shadowToApply) {
69	    if (hidden) {
70	      return;
71	    }
72	    getBounds(boundsRect, parentMatrix, false);
73	
74	    Shader shader;
75	    if (type == GradientType.LINEAR) {
76	      shader = getLinearGradient();
77	    } else {
78	      shader = getRadialGradient();
79	    }
80	    paint.setShader(shader);
81	
82	    super.draw(canvas, parentMatrix, parentAlpha, shadowToApply);
83	  }
