89	  private LinearGradient getLinearGradient() {
90	    int gradientHash = getGradientHash();
91	    LinearGradient gradient = linearGradientCache.get(gradientHash);
92	    if (gradient != null) {
93	      return gradient;
94	    }
95	    PointF startPoint = startPointAnimation.getValue();
96	    PointF endPoint = endPointAnimation.getValue();
97	    GradientColor gradientColor = colorAnimation.getValue();
98	    int[] colors = applyDynamicColorsIfNeeded(gradientColor.getColors());
99	    float[] positions = gradientColor.getPositions();
100	    float x0 = startPoint.x;
101	    float y0 = startPoint.y;
102	    float x1 = endPoint.x;
103	    float y1 = endPoint.y;
104	    gradient = new LinearGradient(x0, y0, x1, y1, colors, positions, Shader.TileMode.CLAMP);
105	    linearGradientCache.put(gradientHash, gradient);
106	    return gradient;
107	  }
108	
109	  private RadialGradient getRadialGradient() {
110	    int gradientHash = getGradientHash();
111	    RadialGradient gradient = radialGradientCache.get(gradientHash);
112	    if (gradient != null) {
113	      return gradient;
114	    }
115	    PointF startPoint = startPointAnimation.getValue();
116	    PointF endPoint = endPointAnimation.getValue();
117	    GradientColor gradientColor = colorAnimation.getValue();
118	    int[] colors = applyDynamicColorsIfNeeded(gradientColor.getColors());
119	    float[] positions = gradientColor.getPositions();
120	    float x0 = startPoint.x;
121	    float y0 = startPoint.y;
122	    float x1 = endPoint.x;
123	    float y1 = endPoint.y;
124	    float r = (float) Math.hypot(x1 - x0, y1 - y0);
125	    gradient = new RadialGradient(x0, y0, r, colors, positions, Shader.TileMode.CLAMP);
126	    radialGradientCache.put(gradientHash, gradient);
127	    return gradient;
128	  }
129	
130	  private int getGradientHash() {
131	    int startPointProgress = Math.round(startPointAnimation.getProgress() * cacheSteps);
132	    int endPointProgress = Math.round(endPointAnimation.getProgress() * cacheSteps);
133	    int colorProgress = Math.round(colorAnimation.getProgress() * cacheSteps);
134	    int hash = 17;
135	    if (startPointProgress != 0) {
136	      hash = hash * 31 * startPointProgress;
137	    }
138	    if (endPointProgress != 0) {
139	      hash = hash * 31 * endPointProgress;
140	    }
141	    if (colorProgress != 0) {
142	      hash = hash * 31 * colorProgress;
143	    }
144	    return hash;
145	  }
146	
147	  private int[] applyDynamicColorsIfNeeded(int[] colors) {
148	    if (colorCallbackAnimation == null) {
149	      return colors;
150	    }
151	    Integer[] dynamicColors = (Integer[]) colorCallbackAnimation.getValue();
152	    int[] result = colors.length == dynamicColors.length ? colors : new int[dynamicColors.length];
153	    for (int i = 0; i < dynamicColors.length; i++) {
154	      result[i] = dynamicColors[i];
155	    }
156	    return result;
157	  }
158	
159	  @Override
160	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
161	    super.addValueCallback(property, callback);
162	    if (property == LottieProperty.GRADIENT_COLOR) {
163	      if (colorCallbackAnimation != null) {
164	        layer.removeAnimation(colorCallbackAnimation);
165	      }
166	
167	      if (callback == null) {
168	        colorCallbackAnimation = null;
169	      } else {
170	        colorCallbackAnimation = new ValueCallbackKeyframeAnimation<>(callback);
171	        colorCallbackAnimation.addUpdateListener(this);
172	        layer.addAnimation(colorCallbackAnimation);
173	      }
174	    }
175	  }
176	}
