27	public class CompositionLayer extends BaseLayer {
28	  @Nullable private BaseKeyframeAnimation<Float, Float> timeRemapping;
29	  private final List<BaseLayer> layers = new ArrayList<>();
30	  private final RectF rect = new RectF();
31	  private final RectF newClipRect = new RectF();
32	  private final RectF layerBounds = new RectF();
