44	  public CompositionLayer(LottieDrawable lottieDrawable, Layer layerModel, List<Layer> layerModels,
45	      LottieComposition composition) {
46	    super(lottieDrawable, layerModel);
47	
48	    AnimatableFloatValue timeRemapping = layerModel.getTimeRemapping();
49	    if (timeRemapping != null) {
50	      this.timeRemapping = timeRemapping.createAnimation();
51	      addAnimation(this.timeRemapping);
52	      //noinspection ConstantConditions
53	      this.timeRemapping.addUpdateListener(this);
54	    } else {
55	      this.timeRemapping = null;
56	    }
57	
58	    LongSparseArray<BaseLayer> layerMap =
59	        new LongSparseArray<>(composition.getLayers().size());
60	
61	    BaseLayer mattedLayer = null;
62	    for (int i = layerModels.size() - 1; i >= 0; i--) {
63	      Layer lm = layerModels.get(i);
64	      BaseLayer layer = BaseLayer.forModel(this, lm, lottieDrawable, composition);
65	      if (layer == null) {
66	        continue;
67	      }
68	      layerMap.put(layer.getLayerModel().getId(), layer);
69	      if (mattedLayer != null) {
70	        mattedLayer.setMatteLayer(layer);
71	        mattedLayer = null;
72	      } else {
73	        layers.add(0, layer);
74	        switch (lm.getMatteType()) {
75	          case ADD:
76	          case INVERT:
77	            mattedLayer = layer;
78	            break;
79	        }
80	      }
81	    }
82	
83	    for (int i = 0; i < layerMap.size(); i++) {
84	      long key = layerMap.keyAt(i);
85	      BaseLayer layerView = layerMap.get(key);
86	      // This shouldn't happen but it appears as if sometimes on pre-lollipop devices when
87	      // compiled with d8, layerView is null sometimes.
88	      // https://github.com/airbnb/lottie-android/issues/524
89	      if (layerView == null) {
90	        continue;
91	      }
92	      BaseLayer parentLayer = layerMap.get(layerView.getLayerModel().getParentId());
93	      if (parentLayer != null) {
94	        layerView.setParentLayer(parentLayer);
95	      }
96	    }
97	
98	    if (getDropShadowEffect() != null) {
99	      dropShadowAnimation = new DropShadowKeyframeAnimation(this, this, getDropShadowEffect());
100	    }
101	  }
