114	  @Override void drawLayer(Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow parentShadowToApply) {
115	    if (L.isTraceEnabled()) {
116	      L.beginSection("CompositionLayer#draw");
117	    }
118	    // Apply off-screen rendering only when needed in order to improve rendering performance.
119	    boolean hasShadow = parentShadowToApply != null || dropShadowAnimation != null;
120	    boolean isDrawingWithOffScreen =
121	        (lottieDrawable.isApplyingOpacityToLayersEnabled() && layers.size() > 1 && parentAlpha != 255) ||
122	            (hasShadow && lottieDrawable.isApplyingShadowToLayersEnabled());
123	    int childAlpha = isDrawingWithOffScreen ? 255 : parentAlpha;
124	
125	    // If we've reached this path with a parentShadowToApply, prioritize the one on our own layer, since we can only support one shadow
126	    // at a time for primitive shapes. If applyShadowsToLayers was true, this would never happen, since it forces the next
127	    // parentShadowToApply to be null (see below).
128	    DropShadow shadowToApply = dropShadowAnimation != null
129	        ? dropShadowAnimation.evaluate(parentMatrix, childAlpha)
130	        : parentShadowToApply;
131	
132	    // Only clip precomps. This mimics the way After Effects renders animations.
133	    boolean ignoreClipOnThisLayer = !clipToCompositionBounds && "__container".equals(layerModel.getName());
134	    if (!ignoreClipOnThisLayer) {
135	      newClipRect.set(0, 0, layerModel.getPreCompWidth(), layerModel.getPreCompHeight());
136	      parentMatrix.mapRect(newClipRect);
137	    } else {
138	      // Calculate the union of all children layer bounds
139	      newClipRect.setEmpty();
140	      for (BaseLayer layer : layers) {
141	        layer.getBounds(layerBounds, parentMatrix, true);
142	        newClipRect.union(layerBounds);
143	      }
144	    }
145	
146	    Canvas targetCanvas = canvas;
147	    if (isDrawingWithOffScreen) {
148	      offscreenOp.reset();
149	      offscreenOp.alpha = parentAlpha;
150	      if (shadowToApply != null) {
151	        shadowToApply.applyTo(offscreenOp);
152	        shadowToApply = null; // OffscreenLayer takes care of shadows when we use it
153	      }
154	      targetCanvas = offscreenLayer.start(canvas, newClipRect, offscreenOp);
155	    }
156	
157	    canvas.save();
158	    if (canvas.clipRect(newClipRect)) {
159	      for (int i = layers.size() - 1; i >= 0; i--) {
160	        BaseLayer layer = layers.get(i);
161	        layer.draw(targetCanvas, parentMatrix, childAlpha, shadowToApply);
162	      }
163	    }
164	
165	    if (isDrawingWithOffScreen) {
166	      offscreenLayer.finish();
167	    }
168	    canvas.restore();
169	
170	    if (L.isTraceEnabled()) {
171	      L.endSection("CompositionLayer#draw");
172	    }
173	  }
