184	  @Override public void setProgress(@FloatRange(from = 0f, to = 1f) float progress) {
185	    if (L.isTraceEnabled()) {
186	      L.beginSection("CompositionLayer#setProgress");
187	    }
188	    this.progress = progress;
189	    super.setProgress(progress);
190	    if (timeRemapping != null) {
191	      // The duration has 0.01 frame offset to show end of animation properly.
192	      // https://github.com/airbnb/lottie-android/pull/766
193	      // Ignore this offset for calculating time-remapping because time-remapping value is based on original duration.
194	      float durationFrames = lottieDrawable.getComposition().getDurationFrames() + 0.01f;
195	      float compositionDelayFrames = layerModel.getComposition().getStartFrame();
196	      float remappedFrames = timeRemapping.getValue() * layerModel.getComposition().getFrameRate() - compositionDelayFrames;
197	      progress = remappedFrames / durationFrames;
198	    }
199	    if (timeRemapping == null) {
200	      progress -= layerModel.getStartProgress();
201	    }
202	    //Time stretch needs to be divided if is not "__container"
203	    if (layerModel.getTimeStretch() != 0 && !"__container".equals(layerModel.getName())) {
204	      progress /= layerModel.getTimeStretch();
205	    }
206	    for (int i = layers.size() - 1; i >= 0; i--) {
207	      layers.get(i).setProgress(progress);
208	    }
209	    if (L.isTraceEnabled()) {
210	      L.endSection("CompositionLayer#setProgress");
211	    }
212	  }
