218	  public boolean hasMasks() {
219	    if (hasMasks == null) {
220	      for (int i = layers.size() - 1; i >= 0; i--) {
221	        BaseLayer layer = layers.get(i);
222	        if (layer instanceof ShapeLayer) {
223	          if (layer.hasMasksOnThisLayer()) {
224	            hasMasks = true;
225	            return true;
226	          }
227	        } else if (layer instanceof CompositionLayer && ((CompositionLayer) layer).hasMasks()) {
228	          hasMasks = true;
229	          return true;
230	        }
231	      }
232	      hasMasks = false;
233	    }
234	    return hasMasks;
235	  }
