237	  public boolean hasMatte() {
238	    if (hasMatte == null) {
239	      if (hasMatteOnThisLayer()) {
240	        hasMatte = true;
241	        return true;
242	      }
243	
244	      for (int i = layers.size() - 1; i >= 0; i--) {
245	        if (layers.get(i).hasMatteOnThisLayer()) {
246	          hasMatte = true;
247	          return true;
248	        }
249	      }
250	      hasMatte = false;
251	    }
252	    return hasMatte;
253	  }
