265	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
266	    super.addValueCallback(property, callback);
267	
268	    if (property == LottieProperty.TIME_REMAP) {
269	      if (callback == null) {
270	        if (timeRemapping != null) {
271	          timeRemapping.setValueCallback(null);
272	        }
273	      } else {
274	        timeRemapping = new ValueCallbackKeyframeAnimation<>((LottieValueCallback<Float>) callback);
275	        timeRemapping.addUpdateListener(this);
276	        addAnimation(timeRemapping);
277	      }
278	    } else if (property == LottieProperty.DROP_SHADOW_COLOR && dropShadowAnimation != null) {
279	      dropShadowAnimation.setColorCallback((LottieValueCallback<Integer>) callback);
280	    } else if (property == LottieProperty.DROP_SHADOW_OPACITY && dropShadowAnimation != null) {
281	      dropShadowAnimation.setOpacityCallback((LottieValueCallback<Float>) callback);
282	    } else if (property == LottieProperty.DROP_SHADOW_DIRECTION && dropShadowAnimation != null) {
283	      dropShadowAnimation.setDirectionCallback((LottieValueCallback<Float>) callback);
284	    } else if (property == LottieProperty.DROP_SHADOW_DISTANCE && dropShadowAnimation != null) {
285	      dropShadowAnimation.setDistanceCallback((LottieValueCallback<Float>) callback);
286	    } else if (property == LottieProperty.DROP_SHADOW_RADIUS && dropShadowAnimation != null) {
287	      dropShadowAnimation.setRadiusCallback((LottieValueCallback<Float>) callback);
288	    }
