70	  private static int floorDiv(int x, int y) {
71	    int r = x / y;
72	    boolean sameSign = (x ^ y) >= 0;
73	    int mod = x % y;
74	    if (!sameSign && mod != 0) {
75	      r--;
76	    }
77	    return r;
