96	  /**
97	   * Helper method for any {@link KeyPathElementContent} that will check if the content
98	   * fully matches the keypath then will add itself as the final key, resolve it, and add
99	   * it to the accumulator list.
100	   * <p>
101	   * Any {@link KeyPathElementContent} should call through to this as its implementation of
102	   * {@link KeyPathElementContent#resolveKeyPath(KeyPath, int, List, KeyPath)}.
103	   */
104	  public static void resolveKeyPath(KeyPath keyPath, int depth, List<KeyPath> accumulator,
105	      KeyPath currentPartialKeyPath, KeyPathElementContent content) {
106	    if (keyPath.fullyResolvesTo(content.getName(), depth)) {
