11	
12	import java.util.ArrayList;
13	import java.util.List;
14	
15	/**
16	 * @param <K> Keyframe type
17	 * @param <A> Animation type
18	 */
19	public abstract class BaseKeyframeAnimation<K, A> {
20	
21	  public interface AnimationListener {
22	
23	    void onValueChanged();
24	  }
25	
26	  // This is not a Set because we don't want to create an iterator object on every setProgress.
27	  final List<AnimationListener> listeners = new ArrayList<>(1);
28	  private boolean isDiscrete = false;
29	
30	  private final KeyframesWrapper<K> keyframesWrapper;
31	  protected float progress = 0f;
32	  @Nullable protected LottieValueCallback<A> valueCallback;
33	
34	  @Nullable private A cachedGetValue = null;
35	
36	  private float cachedStartDelayProgress = -1f;
37	  private float cachedEndProgress = -1f;
38	
39	  BaseKeyframeAnimation(List<? extends Keyframe<K>> keyframes) {
40	    keyframesWrapper = wrap(keyframes);
41	  }
42	
43	  public void setIsDiscrete() {
44	    isDiscrete = true;
45	  }
46	
47	  public void addUpdateListener(AnimationListener listener) {
48	    listeners.add(listener);
49	  }
50	
51	  public void setProgress(@FloatRange(from = 0f, to = 1f) float progress) {
52	    if (L.isTraceEnabled()) {
53	      L.beginSection("BaseKeyframeAnimation#setProgress");
54	    }
55	    if (keyframesWrapper.isEmpty()) {
56	      if (L.isTraceEnabled()) {
57	        L.endSection("BaseKeyframeAnimation#setProgress");
58	      }
59	      return;
60	    }
61	    if (progress < getStartDelayProgress()) {
62	      progress = getStartDelayProgress();
63	    } else if (progress > getEndProgress()) {
64	      progress = getEndProgress();
65	    }
66	
67	    if (progress == this.progress) {
68	      if (L.isTraceEnabled()) {
69	        L.endSection("BaseKeyframeAnimation#setProgress");
70	      }
71	      return;
72	    }
73	    this.progress = progress;
74	    if (keyframesWrapper.isValueChanged(progress)) {
75	      notifyListeners();
76	    }
77	    if (L.isTraceEnabled()) {
78	      L.endSection("BaseKeyframeAnimation#setProgress");
79	    }
80	  }
81	
82	  public void notifyListeners() {
83	    if (L.isTraceEnabled()) {
84	      L.beginSection("BaseKeyframeAnimation#notifyListeners");
85	    }
86	    for (int i = 0; i < listeners.size(); i++) {
87	      listeners.get(i).onValueChanged();
88	    }
89	    if (L.isTraceEnabled()) {
90	      L.endSection("BaseKeyframeAnimation#notifyListeners");
