214	  private static <T> KeyframesWrapper<T> wrap(List<? extends Keyframe<T>> keyframes) {
215	    if (keyframes.isEmpty()) {
216	      return new EmptyKeyframeWrapper<>();
217	    }
218	    if (keyframes.size() == 1) {
219	      return new SingleKeyframeWrapper<>(keyframes);
220	    }
