274	  private static final class SingleKeyframeWrapper<T> implements KeyframesWrapper<T> {
275	
276	    @NonNull
277	    private final Keyframe<T> keyframe;
278	    private float cachedInterpolatedProgress = -1f;
279	
280	    SingleKeyframeWrapper(List<? extends Keyframe<T>> keyframes) {
281	      this.keyframe = keyframes.get(0);
282	    }
283	
284	    @Override
285	    public boolean isEmpty() {
286	      return false;
287	    }
288	
289	    @Override
290	    public boolean isValueChanged(float progress) {
291	      return !keyframe.isStatic();
292	    }
293	
294	    @Override
295	    public Keyframe<T> getCurrentKeyframe() {
296	      return keyframe;
297	    }
298	
299	    @Override
300	    public float getStartDelayProgress() {
301	      return keyframe.getStartProgress();
302	    }
303	
304	    @Override
305	    public float getEndProgress() {
306	      return keyframe.getEndProgress();
307	    }
308	
309	    @Override
310	    public boolean isCachedValueEnabled(float progress) {
311	      if (cachedInterpolatedProgress == progress) {
312	        return true;
313	      }
314	      cachedInterpolatedProgress = progress;
315	      return false;
316	    }
317	  }
318	
319	  private static final class KeyframesWrapperImpl<T> implements KeyframesWrapper<T> {
320	
321	    private final List<? extends Keyframe<T>> keyframes;
322	    @NonNull
323	    private Keyframe<T> currentKeyframe;
324	    private Keyframe<T> cachedCurrentKeyframe = null;
325	    private float cachedInterpolatedProgress = -1f;
326	
327	    KeyframesWrapperImpl(List<? extends Keyframe<T>> keyframes) {
328	      this.keyframes = keyframes;
329	      currentKeyframe = findKeyframe(0);
330	    }
331	
332	    @Override
333	    public boolean isEmpty() {
334	      return false;
335	    }
336	
337	    @Override
338	    public boolean isValueChanged(float progress) {
339	      if (currentKeyframe.containsProgress(progress)) {
340	        return !currentKeyframe.isStatic();
341	      }
342	      currentKeyframe = findKeyframe(progress);
343	      return true;
344	    }
345	
346	    private Keyframe<T> findKeyframe(float progress) {
347	      Keyframe<T> keyframe = keyframes.get(keyframes.size() - 1);
348	      if (progress >= keyframe.getStartProgress()) {
349	        return keyframe;
350	      }
351	      for (int i = keyframes.size() - 2; i >= 1; i--) {
352	        keyframe = keyframes.get(i);
353	        if (currentKeyframe == keyframe) {
354	          continue;
355	        }
356	        if (keyframe.containsProgress(progress)) {
357	          return keyframe;
358	        }
359	      }
360	      return keyframes.get(0);
361	    }
362	
363	    @Override
364	    @NonNull
365	    public Keyframe<T> getCurrentKeyframe() {
366	      return currentKeyframe;
367	    }
368	
369	    @Override
370	    public float getStartDelayProgress() {
371	      return keyframes.get(0).getStartProgress();
372	    }
373	
374	    @Override
375	    public float getEndProgress() {
376	      return keyframes.get(keyframes.size() - 1).getEndProgress();
377	    }
378	
379	    @Override
380	    public boolean isCachedValueEnabled(float progress) {
381	      if (cachedCurrentKeyframe == currentKeyframe
382	          && cachedInterpolatedProgress == progress) {
383	        return true;
384	      }
385	      cachedCurrentKeyframe = currentKeyframe;
386	      cachedInterpolatedProgress = progress;
387	      return false;
388	    }
389	  }
390	}
