48	  @Override public void drawLayer(@NonNull Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow parentShadowToApply) {
49	    Bitmap bitmap = getBitmap();
50	    if (bitmap == null || bitmap.isRecycled() || lottieImageAsset == null) {
51	      return;
52	    }
53	    float density = Utils.dpScale();
54	
55	    paint.setAlpha(parentAlpha);
56	    if (colorFilterAnimation != null) {
57	      paint.setColorFilter(colorFilterAnimation.getValue());
58	    }
59	
60	    @Nullable DropShadow shadowToApply = dropShadowAnimation != null
61	        ? dropShadowAnimation.evaluate(parentMatrix, parentAlpha)
62	        : parentShadowToApply;
63	
64	    src.set(0, 0, bitmap.getWidth(), bitmap.getHeight());
65	    if (lottieDrawable.getMaintainOriginalImageBounds()) {
66	      dst.set(0, 0, (int) (lottieImageAsset.getWidth() * density), (int) (lottieImageAsset.getHeight() * density));
67	    } else {
68	      dst.set(0, 0, (int) (bitmap.getWidth() * density), (int) (bitmap.getHeight() * density));
69	    }
70	
71	    // Render off-screen if we have a drop shadow, because:
72	    // - Android does not apply drop-shadows to bitmaps properly in HW accelerated contexts (blur is ignored)
73	    // - On some newer phones (empirically verified), no shadow is rendered at all even in software contexts.
74	    boolean renderOffScreen = shadowToApply != null;
75	    Canvas targetCanvas = canvas;
76	    if (renderOffScreen) {
77	      if (offscreenLayer == null) offscreenLayer = new OffscreenLayer();
78	      if (offscreenOp == null) offscreenOp = new OffscreenLayer.ComposeOp();
79	      offscreenOp.reset();
80	      // We don't use offscreenOp for compositing here, so we still need to account for its alpha
81	      // when drawing the shadow.
82	      shadowToApply.applyWithAlpha(parentAlpha, offscreenOp);
83	
84	
85	      // We don't use getBounds() as it expects the parent-to-world matrix, and what we have in parentMatrix is in
86	      // fact us-to-world (parent-to-world * us-to-parent)
87	      layerBounds.set(dst.left, dst.top, dst.right, dst.bottom);
88	      parentMatrix.mapRect(layerBounds);
89	      targetCanvas = offscreenLayer.start(canvas, layerBounds, offscreenOp);
90	    }
91	
92	    targetCanvas.save();
93	    targetCanvas.concat(parentMatrix);
94	    targetCanvas.drawBitmap(bitmap, src, dst, paint);
95	
96	    if (renderOffScreen) {
97	      offscreenLayer.finish();
98	      if (offscreenLayer.finishDecrementsCanvasSaveCount()) {
99	        return; // Don't need a restore() call since it's handled by OffscreenLayer
100	      }
101	    }
102	
103	    targetCanvas.restore();
104	  }
105	
106	  @Override public void getBounds(RectF outBounds, Matrix parentMatrix, boolean applyParents) {
107	    super.getBounds(outBounds, parentMatrix, applyParents);
108	    if (lottieImageAsset != null) {
109	      float scale = Utils.dpScale();
110	      int assetWidth = lottieImageAsset.getWidth();
111	      int assetHeight = lottieImageAsset.getHeight();
112	      if (lottieDrawable.getMaintainOriginalImageBounds()) {
113	        outBounds.set(0, 0, assetWidth * scale, assetHeight * scale);
114	      } else {
115	        Bitmap bitmap = getBitmap();
116	        if (bitmap != null) {
117	          outBounds.set(0, 0, bitmap.getWidth() * scale, bitmap.getHeight() * scale);
118	        } else {
119	          // If the bitmap is null, fall back to using the width and height of the LottieImageAsset
120	          outBounds.set(0, 0, assetWidth * scale, assetHeight * scale);
121	        }
122	      }
123	      boundsMatrix.mapRect(outBounds);
124	    }
125	  }
