131	      if (callbackBitmap != null) {
132	        return callbackBitmap;
133	      }
134	    }
135	    String refId = layerModel.getRefId();
136	    Bitmap bitmapFromDrawable = lottieDrawable.getBitmapForId(refId);
137	    if (bitmapFromDrawable != null) {
138	      return bitmapFromDrawable;
139	    }
140	    LottieImageAsset asset = this.lottieImageAsset;
141	    if (asset != null) {
142	      return asset.getBitmap();
143	    }
144	    return null;
145	  }
