157	            new ValueCallbackKeyframeAnimation<>((LottieValueCallback<ColorFilter>) callback);
158	      }
159	    } else if (property == LottieProperty.IMAGE) {
160	      if (callback == null) {
161	        imageAnimation = null;
162	      } else {
163	        //noinspection unchecked
164	        imageAnimation =
165	            new ValueCallbackKeyframeAnimation<>((LottieValueCallback<Bitmap>) callback);
166	      }
167	    } else if (property == LottieProperty.DROP_SHADOW_COLOR && dropShadowAnimation != null) {
168	        dropShadowAnimation.setColorCallback((LottieValueCallback<Integer>) callback);
169	    } else if (property == LottieProperty.DROP_SHADOW_OPACITY && dropShadowAnimation != null) {
