219	  public Matrix getMatrix() {
220	    matrix.reset();
221	
222	    float rotX = rotationX != null ? rotationX.getFloatValue() : 0f;
223	    float rotY = rotationY != null ? rotationY.getFloatValue() : 0f;
224	    float rotZ = rotationZ != null ? rotationZ.getFloatValue() : 0f;
225	    boolean has3DRotation = rotX != 0f || rotY != 0f || rotZ != 0f;
226	
227	    // If there is 3D rotation, use the new Transform3D utility class
228	    if (has3DRotation) {
229	
230	      // Update cache if values changed (Float.NaN initial values ensure first-call recalculation)
231	      if (rotX != cachedRotationX || rotY != cachedRotationY || rotZ != cachedRotationZ) {
232	        cachedRotationX = rotX;
233	        cachedRotationY = rotY;
234	        cachedRotationZ = rotZ;
235	        cachedCosX = rotX != 0f ? (float) Math.cos(Math.toRadians(rotX)) : 1f;
236	        cachedCosY = rotY != 0f ? (float) Math.cos(Math.toRadians(rotY)) : 1f;
237	      }
238	
239	      PointF anchorPointValue = anchorPoint == null ? null : anchorPoint.getValue();
240	      PointF positionValue = position == null ? null : position.getValue();
241	      ScaleXY scaleValue = scale == null ? null : scale.getValue();
242	
243	      // Extract scale values (default 1f, consistent with original code)
244	      float scaleX = scaleValue != null ? scaleValue.getScaleX() : 1f;
245	      float scaleY = scaleValue != null ? scaleValue.getScaleY() : 1f;
246	
247	      // Use Transform3D to calculate complete 3D transformation with cached cos values
248	      Transform3D.applyTransform(
249	        matrix,
250	        anchorPointValue,
251	        positionValue,
252	        scaleX,
253	        scaleY,
254	        rotX,
255	        rotY,
256	        rotZ,
257	        cachedCosX,
258	        cachedCosY
259	      );
260	
261	      return matrix;
262	    }
263	    BaseKeyframeAnimation<?, PointF> position = this.position;
264	    if (position != null) {
265	      PointF positionValue = position.getValue();
266	      if (positionValue != null && (positionValue.x != 0 || positionValue.y != 0)) {
267	        matrix.preTranslate(positionValue.x, positionValue.y);
268	      }
269	    }
270	
271	    // If autoOrient is true, the rotation should follow the derivative of the position rather
272	    // than the rotation property.
273	    if (autoOrient) {
274	      if (position != null) {
275	        float currentProgress = position.getProgress();
276	        PointF startPosition = position.getValue();
277	        // Store the start X and Y values because the pointF will be overwritten by the next getValue call.
278	        float startX = startPosition.x;
279	        float startY = startPosition.y;
280	        // 1) Find the next position value.
281	        // 2) Create a vector from the current position to the next position.
282	        // 3) Find the angle of that vector to the X axis (0 degrees).
283	        position.setProgress(currentProgress + 0.0001f);
284	        PointF nextPosition = position.getValue();
285	        position.setProgress(currentProgress);
286	        double rotationValue = Math.toDegrees(Math.atan2(nextPosition.y - startY, nextPosition.x - startX));
287	        matrix.preRotate((float) rotationValue);
288	      }
289	    } else {
290	      BaseKeyframeAnimation<Float, Float> rotation = this.rotation;
291	      if (rotation != null) {
292	        float rotationValue;
293	        if (rotation instanceof ValueCallbackKeyframeAnimation) {
294	          rotationValue = rotation.getValue();
295	        } else {
296	          rotationValue = ((FloatKeyframeAnimation) rotation).getFloatValue();
297	        }
298	        if (rotationValue != 0f) {
299	          matrix.preRotate(rotationValue);
300	        }
301	      }
302	    }
303	
304	    FloatKeyframeAnimation skew = this.skew;
305	    if (skew != null) {
306	      float mCos = skewAngle == null ? 0f : (float) Math.cos(Math.toRadians(-skewAngle.getFloatValue() + 90));
307	      float mSin = skewAngle == null ? 1f : (float) Math.sin(Math.toRadians(-skewAngle.getFloatValue() + 90));
308	      float aTan = (float) Math.tan(Math.toRadians(skew.getFloatValue()));
309	      clearSkewValues();
310	      skewValues[0] = mCos;
311	      skewValues[1] = mSin;
312	      skewValues[3] = -mSin;
313	      skewValues[4] = mCos;
314	      skewValues[8] = 1f;
315	      skewMatrix1.setValues(skewValues);
316	      clearSkewValues();
317	      skewValues[0] = 1f;
318	      skewValues[3] = aTan;
319	      skewValues[4] = 1f;
320	      skewValues[8] = 1f;
321	      skewMatrix2.setValues(skewValues);
322	      clearSkewValues();
323	      skewValues[0] = mCos;
324	      skewValues[1] = -mSin;
325	      skewValues[3] = mSin;
326	      skewValues[4] = mCos;
327	      skewValues[8] = 1;
328	      skewMatrix3.setValues(skewValues);
329	      skewMatrix2.preConcat(skewMatrix1);
330	      skewMatrix3.preConcat(skewMatrix2);
331	
332	      matrix.preConcat(skewMatrix3);
333	    }
334	
335	    BaseKeyframeAnimation<ScaleXY, ScaleXY> scale = this.scale;
336	    if (scale != null) {
337	      ScaleXY scaleTransform = scale.getValue();
338	      if (scaleTransform != null && (scaleTransform.getScaleX() != 1f || scaleTransform.getScaleY() != 1f)) {
339	        matrix.preScale(scaleTransform.getScaleX(), scaleTransform.getScaleY());
340	      }
341	    }
342	
343	    BaseKeyframeAnimation<PointF, PointF> anchorPoint = this.anchorPoint;
344	    if (anchorPoint != null) {
345	      PointF anchorPointValue = anchorPoint.getValue();
346	      if (anchorPointValue != null && (anchorPointValue.x != 0 || anchorPointValue.y != 0)) {
347	        matrix.preTranslate(-anchorPointValue.x, -anchorPointValue.y);
348	      }
349	    }
350	
351	    return matrix;
352	  }
