358	  /**
359	   * Get transformation matrix for repeater content.
360	   * This method applies transformations scaled by the amount parameter.
361	   *
362	   * @param amount Scaling factor for all transformations (based on copy index + offset)
363	   */
364	  public Matrix getMatrixForRepeater(float amount) {
365	    PointF position = this.position == null ? null : this.position.getValue();
366	    ScaleXY scale = this.scale == null ? null : this.scale.getValue();
367	    PointF anchorPoint = this.anchorPoint == null ? null : this.anchorPoint.getValue();
368	
369	    matrix.reset();
370	
371	    // 1. Apply position transformation
372	    if (position != null) {
373	      matrix.preTranslate(position.x * amount, position.y * amount);
374	    }
375	
376	    // 2. Apply rotation transformations
377	    // Check for 3D rotation
378	    float rotX = rotationX != null ? rotationX.getFloatValue() * amount : 0f;
379	    float rotY = rotationY != null ? rotationY.getFloatValue() * amount : 0f;
380	    float rotZ = rotationZ != null ? rotationZ.getFloatValue() * amount : 0f;
381	
382	    boolean has3DRotation = rotX != 0f || rotY != 0f || rotZ != 0f;
383	
384	    if (has3DRotation) {
385	      // Pre-compute cosine values once for this call
386	      float cosX = rotX != 0f ? (float) Math.cos(Math.toRadians(rotX)) : 1f;
387	      float cosY = rotY != 0f ? (float) Math.cos(Math.toRadians(rotY)) : 1f;
388	
389	      // Apply Z-axis rotation around anchor point
390	      if (rotZ != 0f) {
391	        float anchorX = anchorPoint == null ? 0f : anchorPoint.x;
392	        float anchorY = anchorPoint == null ? 0f : anchorPoint.y;
393	        matrix.preRotate(rotZ, anchorX, anchorY);
394	      }
395	
396	      // Apply 3D rotations using Transform3D utility (X and Y only, as Z was already applied)
397	      Transform3D.apply3DRotations(matrix, rotX, rotY, 0f, cosX, cosY);
398	    } else if (this.rotation != null) {
399	      // Fall back to 2D rotation
400	      float anchorX = anchorPoint == null ? 0f : anchorPoint.x;
401	      float anchorY = anchorPoint == null ? 0f : anchorPoint.y;
402	      matrix.preRotate(this.rotation.getValue() * amount, anchorX, anchorY);
403	    }
404	
405	    // 3. Apply scale transformation
406	    if (scale != null) {
407	      matrix.preScale(
408	          (float) Math.pow(scale.getScaleX(), amount),
409	          (float) Math.pow(scale.getScaleY(), amount));
410	    }
411	
412	    return matrix;
413	  }
