416	   * Returns whether the callback was applied.
417	   */
418	  @SuppressWarnings("unchecked")
419	  public <T> boolean applyValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
420	    if (property == TRANSFORM_ANCHOR_POINT) {
421	      if (anchorPoint == null) {
422	        anchorPoint = new ValueCallbackKeyframeAnimation<>((LottieValueCallback<PointF>) callback, new PointF());
423	      } else {
424	        anchorPoint.setValueCallback((LottieValueCallback<PointF>) callback);
425	      }
426	    } else if (property == TRANSFORM_POSITION) {
427	      if (position == null) {
428	        position = new ValueCallbackKeyframeAnimation<>((LottieValueCallback<PointF>) callback, new PointF());
429	      } else {
430	        position.setValueCallback((LottieValueCallback<PointF>) callback);
431	      }
432	    } else if (property == TRANSFORM_POSITION_X && position instanceof SplitDimensionPathKeyframeAnimation) {
433	      ((SplitDimensionPathKeyframeAnimation) position).setXValueCallback((LottieValueCallback<Float>) callback);
434	    } else if (property == TRANSFORM_POSITION_Y && position instanceof SplitDimensionPathKeyframeAnimation) {
435	      ((SplitDimensionPathKeyframeAnimation) position).setYValueCallback((LottieValueCallback<Float>) callback);
436	    } else if (property == TRANSFORM_SCALE) {
437	      if (scale == null) {
438	        scale = new ValueCallbackKeyframeAnimation<>((LottieValueCallback<ScaleXY>) callback, new ScaleXY());
439	      } else {
440	        scale.setValueCallback((LottieValueCallback<ScaleXY>) callback);
441	      }
442	    } else if (property == TRANSFORM_ROTATION) {
443	      if (rotation == null) {
444	        rotation = new ValueCallbackKeyframeAnimation<>((LottieValueCallback<Float>) callback, 0f);
445	      } else {
446	        rotation.setValueCallback((LottieValueCallback<Float>) callback);
447	      }
448	    } else if (property == TRANSFORM_OPACITY) {
449	      if (opacity == null) {
450	        opacity = new ValueCallbackKeyframeAnimation<>((LottieValueCallback<Integer>) callback, 100);
451	      } else {
452	        opacity.setValueCallback((LottieValueCallback<Integer>) callback);
453	      }
454	    } else if (property == TRANSFORM_START_OPACITY) {
455	      if (startOpacity == null) {
456	        startOpacity = new ValueCallbackKeyframeAnimation<>((LottieValueCallback<Float>) callback, 100f);
457	      } else {
458	        startOpacity.setValueCallback((LottieValueCallback<Float>) callback);
459	      }
460	    } else if (property == TRANSFORM_END_OPACITY) {
461	      if (endOpacity == null) {
462	        endOpacity = new ValueCallbackKeyframeAnimation<>((LottieValueCallback<Float>) callback, 100f);
463	      } else {
464	        endOpacity.setValueCallback((LottieValueCallback<Float>) callback);
465	      }
466	    } else if (property == TRANSFORM_SKEW) {
467	      if (skew == null) {
468	        skew = new FloatKeyframeAnimation(Collections.singletonList(new Keyframe<>(0f)));
469	      }
470	      skew.setValueCallback((LottieValueCallback<Float>) callback);
471	    } else if (property == TRANSFORM_SKEW_ANGLE) {
472	      if (skewAngle == null) {
473	        skewAngle = new FloatKeyframeAnimation(Collections.singletonList(new Keyframe<>(0f)));
474	      }
475	      skewAngle.setValueCallback((LottieValueCallback<Float>) callback);
476	    } else if (property == TRANSFORM_ROTATION_X) {
477	      if (rotationX == null) {
478	        rotationX = new FloatKeyframeAnimation(Collections.singletonList(new Keyframe<>(0f)));
479	      }
480	      rotationX.setValueCallback((LottieValueCallback<Float>) callback);
481	    } else if (property == TRANSFORM_ROTATION_Y) {
482	      if (rotationY == null) {
483	        rotationY = new FloatKeyframeAnimation(Collections.singletonList(new Keyframe<>(0f)));
484	      }
485	      rotationY.setValueCallback((LottieValueCallback<Float>) callback);
486	    } else if (property == TRANSFORM_ROTATION_Z) {
487	      if (rotationZ == null) {
488	        rotationZ = new FloatKeyframeAnimation(Collections.singletonList(new Keyframe<>(0f)));
489	      }
490	      rotationZ.setValueCallback((LottieValueCallback<Float>) callback);
491	    } else {
492	      return false;
493	    }
494	    return true;
495	  }
