18	
19	import java.io.IOException;
20	import java.lang.ref.WeakReference;
21	
22	class KeyframeParser {
23	  /**
24	   * Some animations get exported with insane cp values in the tens of thousands.
25	   * PathInterpolator fails to create the interpolator in those cases and hangs.
26	   * Clamping the cp helps prevent that.
27	   */
28	  private static final float MAX_CP_VALUE = 100;
29	  private static final Interpolator LINEAR_INTERPOLATOR = new LinearInterpolator();
30	  private static SparseArrayCompat<WeakReference<Interpolator>> pathInterpolatorCache;
31	
32	  static JsonReader.Options NAMES = JsonReader.Options.of(
33	      "t",  // 1
34	      "s",  // 2
35	      "e",  // 3
36	      "o",  // 4
37	      "i",  // 5
38	      "h",  // 6
39	      "to", // 7
40	      "ti"  // 8
41	  );
42	  static JsonReader.Options INTERPOLATOR_NAMES = JsonReader.Options.of(
43	      "x",  // 1
44	      "y"   // 2
45	  );
46	
47	  // https://github.com/airbnb/lottie-android/issues/464
48	  private static SparseArrayCompat<WeakReference<Interpolator>> pathInterpolatorCache() {
49	    if (pathInterpolatorCache == null) {
50	      pathInterpolatorCache = new SparseArrayCompat<>();
51	    }
52	    return pathInterpolatorCache;
53	  }
54	
55	  @Nullable
56	  private static WeakReference<Interpolator> getInterpolator(int hash) {
57	    // This must be synchronized because get and put isn't thread safe because
58	    // SparseArrayCompat has to create new sized arrays sometimes.
59	    synchronized (KeyframeParser.class) {
60	      return pathInterpolatorCache().get(hash);
61	    }
62	  }
63	
64	  private static void putInterpolator(int hash, WeakReference<Interpolator> interpolator) {
65	    // This must be synchronized because get and put isn't thread safe because
66	    // SparseArrayCompat has to create new sized arrays sometimes.
67	    synchronized (KeyframeParser.class) {
68	      pathInterpolatorCache.put(hash, interpolator);
69	    }
70	  }
71	
72	  /**
73	   * @param multiDimensional When true, the keyframe interpolators can be independent for the X and Y axis.
74	   */
75	  static <T> Keyframe<T> parse(JsonReader reader, LottieComposition composition,
76	      float scale, ValueParser<T> valueParser, boolean animated, boolean multiDimensional) throws IOException {
77	
78	    if (animated && multiDimensional) {
79	      return parseMultiDimensionalKeyframe(composition, reader, scale, valueParser);
80	    } else if (animated) {
81	      return parseKeyframe(composition, reader, scale, valueParser);
82	    } else {
83	      return parseStaticValue(reader, scale, valueParser);
84	    }
85	  }
86	
87	  /**
88	   * beginObject will already be called on the keyframe so it can be differentiated with
89	   * a non animated value.
90	   */
91	  private static <T> Keyframe<T> parseKeyframe(LottieComposition composition, JsonReader reader,
92	      float scale, ValueParser<T> valueParser) throws IOException {
93	    PointF cp1 = null;
94	    PointF cp2 = null;
95	
96	    float startFrame = 0;
97	    T startValue = null;
98	    T endValue = null;
99	    boolean hold = false;
100	    Interpolator interpolator = null;
101	
102	    // Only used by PathKeyframe
103	    PointF pathCp1 = null;
104	    PointF pathCp2 = null;
105	
106	    reader.beginObject();
107	    while (reader.hasNext()) {
108	      switch (reader.selectName(NAMES)) {
109	        case 0: // t
110	          startFrame = (float) reader.nextDouble();
111	          break;
112	        case 1: // s
113	          startValue = valueParser.parse(reader, scale);
114	          break;
115	        case 2: // e
116	          endValue = valueParser.parse(reader, scale);
117	          break;
118	        case 3: // o
119	          cp1 = JsonUtils.jsonToPoint(reader, 1f);
120	          break;
121	        case 4: // i
122	          cp2 = JsonUtils.jsonToPoint(reader, 1f);
123	          break;
124	        case 5: // h
125	          hold = reader.nextInt() == 1;
126	          break;
127	        case 6: // to
128	          pathCp1 = JsonUtils.jsonToPoint(reader, scale);
129	          break;
130	        case 7: // ti
131	          pathCp2 = JsonUtils.jsonToPoint(reader, scale);
132	          break;
133	        default:
134	          reader.skipValue();
135	      }
136	    }
137	    reader.endObject();
138	
139	    if (hold) {
140	      endValue = startValue;
141	      // TODO: create a HoldInterpolator so progress changes don't invalidate.
142	      interpolator = LINEAR_INTERPOLATOR;
143	    } else if (cp1 != null && cp2 != null) {
144	      interpolator = interpolatorFor(cp1, cp2);
145	    } else {
146	      interpolator = LINEAR_INTERPOLATOR;
147	    }
148	
149	    Keyframe<T> keyframe = new Keyframe<>(composition, startValue, endValue, interpolator, startFrame, null);
150	
151	    keyframe.pathCp1 = pathCp1;
152	    keyframe.pathCp2 = pathCp2;
153	    return keyframe;
154	  }
155	
156	  private static <T> Keyframe<T> parseMultiDimensionalKeyframe(LottieComposition composition, JsonReader reader,
157	      float scale, ValueParser<T> valueParser) throws IOException {
158	    PointF cp1 = null;
159	    PointF cp2 = null;
160	
161	    PointF xCp1 = null;
162	    PointF xCp2 = null;
163	    PointF yCp1 = null;
164	    PointF yCp2 = null;
165	
166	    float startFrame = 0;
167	    T startValue = null;
168	    T endValue = null;
169	    boolean hold = false;
170	    Interpolator interpolator = null;
171	    Interpolator xInterpolator = null;
172	    Interpolator yInterpolator = null;
173	
174	    // Only used by PathKeyframe
175	    PointF pathCp1 = null;
176	    PointF pathCp2 = null;
177	
178	    reader.beginObject();
179	    while (reader.hasNext()) {
180	      switch (reader.selectName(NAMES)) {
181	        case 0: // t
182	          startFrame = (float) reader.nextDouble();
183	          break;
184	        case 1: // s
185	          startValue = valueParser.parse(reader, scale);
186	          break;
187	        case 2: // e
188	          endValue = valueParser.parse(reader, scale);
189	          break;
190	        case 3: // o
191	          if (reader.peek() == JsonReader.Token.BEGIN_OBJECT) {
192	            PointF[] cp1s = parseMultiDimensionalControlPoint(reader);
193	            xCp1 = cp1s[0];
194	            yCp1 = cp1s[1];
195	          } else {
196	            cp1 = JsonUtils.jsonToPoint(reader, scale);
197	          }
198	          break;
199	        case 4: // i
200	          if (reader.peek() == JsonReader.Token.BEGIN_OBJECT) {
201	            PointF[] cp2s = parseMultiDimensionalControlPoint(reader);
202	            xCp2 = cp2s[0];
203	            yCp2 = cp2s[1];
204	          } else {
205	            cp2 = JsonUtils.jsonToPoint(reader, scale);
206	          }
207	          break;
208	        case 5: // h
209	          hold = reader.nextInt() == 1;
210	          break;
211	        case 6: // to
212	          pathCp1 = JsonUtils.jsonToPoint(reader, scale);
213	          break;
214	        case 7: // ti
215	          pathCp2 = JsonUtils.jsonToPoint(reader, scale);
216	          break;
217	        default:
218	          reader.skipValue();
219	      }
220	    }
221	    reader.endObject();
222	
223	    if (hold) {
224	      endValue = startValue;
225	      // TODO: create a HoldInterpolator so progress changes don't invalidate.
226	      interpolator = LINEAR_INTERPOLATOR;
227	    } else if (cp1 != null && cp2 != null) {
228	      interpolator = interpolatorFor(cp1, cp2);
229	    } else if (xCp1 != null && yCp1 != null && xCp2 != null && yCp2 != null) {
230	      xInterpolator = interpolatorFor(xCp1, xCp2);
231	      yInterpolator = interpolatorFor(yCp1, yCp2);
232	    } else {
233	      interpolator = LINEAR_INTERPOLATOR;
234	    }
235	
236	    Keyframe<T> keyframe;
237	    if (xInterpolator != null && yInterpolator != null) {
238	      keyframe = new Keyframe<>(composition, startValue, endValue, xInterpolator, yInterpolator, startFrame, null);
239	    } else {
240	      keyframe = new Keyframe<>(composition, startValue, endValue, interpolator, startFrame, null);
241	    }
242	
243	    keyframe.pathCp1 = pathCp1;
244	    keyframe.pathCp2 = pathCp2;
245	    return keyframe;
246	  }
247	
248	  private static PointF[] parseMultiDimensionalControlPoint(JsonReader reader) throws IOException {
249	    float xCpx = 0f;
250	    float xCpy = 0f;
251	    float yCpx = 0f;
252	    float yCpy = 0f;
253	    reader.beginObject();
254	    while (reader.hasNext()) {
255	      switch (reader.selectName(INTERPOLATOR_NAMES)) {
256	        case 0: // x
257	          if (reader.peek() == JsonReader.Token.NUMBER) {
258	            xCpx = (float) reader.nextDouble();
259	            yCpx = xCpx;
260	          } else {
261	            reader.beginArray();
262	            xCpx = (float) reader.nextDouble();
263	            if (reader.peek() == JsonReader.Token.NUMBER) {
264	              yCpx = (float) reader.nextDouble();
265	            } else {
266	              yCpx = xCpx;
267	            }
268	            reader.endArray();
269	          }
270	          break;
271	        case 1: // y
272	          if (reader.peek() == JsonReader.Token.NUMBER) {
273	            xCpy = (float) reader.nextDouble();
274	            yCpy = xCpy;
275	          } else {
276	            reader.beginArray();
277	            xCpy = (float) reader.nextDouble();
278	            if (reader.peek() == JsonReader.Token.NUMBER) {
279	              yCpy = (float) reader.nextDouble();
280	            } else {
281	              yCpy = xCpy;
282	            }
283	            reader.endArray();
284	          }
285	          break;
286	        default:
287	          reader.skipValue();
288	      }
289	    }
290	    reader.endObject();
291	    return new PointF[]{new PointF(xCpx, xCpy), new PointF(yCpx, yCpy)};
292	  }
293	
294	  private static Interpolator interpolatorFor(PointF cp1, PointF cp2) {
295	    Interpolator interpolator = null;
296	    cp1.x = MiscUtils.clamp(cp1.x, -1f, 1f);
297	    cp1.y = MiscUtils.clamp(cp1.y, -MAX_CP_VALUE, MAX_CP_VALUE);
298	    cp2.x = MiscUtils.clamp(cp2.x, -1f, 1f);
299	    cp2.y = MiscUtils.clamp(cp2.y, -MAX_CP_VALUE, MAX_CP_VALUE);
300	    int hash = Utils.hashFor(cp1.x, cp1.y, cp2.x, cp2.y);
301	    WeakReference<Interpolator> interpolatorRef = L.getDisablePathInterpolatorCache() ? null : getInterpolator(hash);
302	    if (interpolatorRef != null) {
303	      interpolator = interpolatorRef.get();
304	    }
305	    if (interpolatorRef == null || interpolator == null) {
306	      try {
307	        interpolator = PathInterpolatorCompat.create(cp1.x, cp1.y, cp2.x, cp2.y);
308	      } catch (IllegalArgumentException e) {
309	        if ("The Path cannot loop back on itself.".equals(e.getMessage())) {
310	          // If a control point extends beyond the previous/next point then it will cause the value of the interpolator to no
311	          // longer monotonously increase. This clips the control point bounds to prevent that from happening.
312	          // NOTE: this will make the rendered animation behave slightly differently than the original.
313	          interpolator = PathInterpolatorCompat.create(Math.min(cp1.x, 1f), cp1.y, Math.max(cp2.x, 0f), cp2.y);
314	        } else {
315	          // We failed to create the interpolator. Fall back to linear.
316	          interpolator = new LinearInterpolator();
317	        }
318	      }
319	      if (!L.getDisablePathInterpolatorCache()) {
320	        try {
321	          putInterpolator(hash, new WeakReference<>(interpolator));
322	        } catch (ArrayIndexOutOfBoundsException e) {
323	          // It is not clear why but SparseArrayCompat sometimes fails with this:
324	          //     https://github.com/airbnb/lottie-android/issues/452
325	          // Because this is not a critical operation, we can safely just ignore it.
326	          // I was unable to repro this to attempt a proper fix.
327	        }
328	      }
329	    }
330	    return interpolator;
331	  }
332	
333	  private static <T> Keyframe<T> parseStaticValue(JsonReader reader,
334	      float scale, ValueParser<T> valueParser) throws IOException {
335	    T value = valueParser.parse(reader, scale);
336	    return new Keyframe<>(value);
337	  }
338	}
