1	package com.airbnb.lottie.utils;
2	
3	import android.animation.ValueAnimator;
4	import android.view.Choreographer;
5	
6	import androidx.annotation.FloatRange;
7	import androidx.annotation.MainThread;
8	import androidx.annotation.Nullable;
9	import androidx.annotation.VisibleForTesting;
10	
11	import com.airbnb.lottie.L;
12	import com.airbnb.lottie.LottieComposition;
13	
14	/**
15	 * This is a slightly modified {@link ValueAnimator} that allows us to update start and end values
16	 * easily optimizing for the fact that we know that it's a value animator with 2 floats.
17	 */
18	public class LottieValueAnimator extends BaseLottieAnimator implements Choreographer.FrameCallback {
19	
20	
21	  private float speed = 1f;
22	  private boolean speedReversedForRepeatMode = false;
23	  private long lastFrameTimeNs = 0;
24	  private float frameRaw = 0;
25	  private float frame = 0;
26	  private int repeatCount = 0;
27	  private float minFrame = Integer.MIN_VALUE;
28	  private float maxFrame = Integer.MAX_VALUE;
29	  @Nullable private LottieComposition composition;
30	  @VisibleForTesting protected boolean running = false;
31	  private boolean useCompositionFrameRate = false;
32	
33	  public LottieValueAnimator() {
34	  }
35	
36	  /**
37	   * Returns a float representing the current value of the animation from 0 to 1
38	   * regardless of the animation speed, direction, or min and max frames.
39	   */
40	  @Override public Object getAnimatedValue() {
41	    return getAnimatedValueAbsolute();
42	  }
43	
44	  /**
45	   * Returns the current value of the animation from 0 to 1 regardless
46	   * of the animation speed, direction, or min and max frames.
47	   */
48	  @FloatRange(from = 0f, to = 1f) public float getAnimatedValueAbsolute() {
49	    if (composition == null) {
50	      return 0;
51	    }
52	    float startFrame = composition.getStartFrame();
53	    float endFrame = composition.getEndFrame();
54	    return (frame - startFrame) / (endFrame - startFrame);
55	
56	  }
57	
58	  /**
59	   * Returns the current value of the currently playing animation taking into
60	   * account direction, min and max frames.
61	   */
62	  @Override @FloatRange(from = 0f, to = 1f) public float getAnimatedFraction() {
63	    if (composition == null) {
64	      return 0;
65	    }
66	    float minFrame = getMinFrame();
67	    float maxFrame = getMaxFrame();
68	    if (isReversed()) {
69	      return (maxFrame - frame) / (maxFrame - minFrame);
70	    } else {
71	      return (frame - minFrame) / (maxFrame - minFrame);
72	    }
73	  }
74	
75	  @Override public long getDuration() {
76	    return composition == null ? 0 : (long) composition.getDuration();
77	  }
78	
79	  public float getFrame() {
80	    return frame;
81	  }
82	
83	  @Override public boolean isRunning() {
84	    return running;
85	  }
86	
87	  public void setUseCompositionFrameRate(boolean useCompositionFrameRate) {
88	    this.useCompositionFrameRate = useCompositionFrameRate;
89	  }
90	
91	  @Override public void doFrame(long frameTimeNanos) {
92	    postFrameCallback();
93	    if (composition == null || !isRunning()) {
94	      return;
95	    }
96	
97	    if (L.isTraceEnabled()) {
98	      L.beginSection("LottieValueAnimator#doFrame");
99	    }
100	    long timeSinceFrame = lastFrameTimeNs == 0 ? 0 : frameTimeNanos - lastFrameTimeNs;
101	    float frameDuration = getFrameDurationNs();
102	    float dFrames = timeSinceFrame / frameDuration;
103	
104	    float minFrame = getMinFrame();
105	    float maxFrame = getMaxFrame();
106	    float newFrameRaw = frameRaw + (isReversed() ? -dFrames : dFrames);
107	    boolean ended = !MiscUtils.contains(newFrameRaw, minFrame, maxFrame);
108	    float previousFrameRaw = frameRaw;
109	    frameRaw = MiscUtils.clamp(newFrameRaw, minFrame, maxFrame);
110	    frame = useCompositionFrameRate ? (float) Math.floor(frameRaw) : frameRaw;
111	
112	    lastFrameTimeNs = frameTimeNanos;
113	
114	    if (ended) {
115	      if (getRepeatCount() != INFINITE && repeatCount >= getRepeatCount()) {
116	        frameRaw = speed < 0 ? minFrame : maxFrame;
117	        frame = frameRaw;
118	        removeFrameCallback();
119	        checkNotifyUpdate(previousFrameRaw);
120	        notifyEnd(isReversed());
121	      } else {
122	        if (getRepeatMode() == REVERSE) {
123	          speedReversedForRepeatMode = !speedReversedForRepeatMode;
124	          reverseAnimationSpeed();
125	        } else {
126	          frameRaw = isReversed() ? maxFrame : minFrame;
127	          frame = frameRaw;
128	        }
129	        lastFrameTimeNs = frameTimeNanos;
130	        checkNotifyUpdate(previousFrameRaw);
131	        notifyRepeat();
132	        repeatCount++;
133	      }
134	    } else {
135	      checkNotifyUpdate(previousFrameRaw);
136	    }
137	
138	    verifyFrame();
139	    if (L.isTraceEnabled()) {
140	      L.endSection("LottieValueAnimator#doFrame");
141	    }
142	  }
143	
144	  private void checkNotifyUpdate(float previousFrameRaw) {
145	    if (!useCompositionFrameRate || frameRaw != previousFrameRaw) {
146	      notifyUpdate();
147	    }
148	  }
149	
150	  private float getFrameDurationNs() {
151	    if (composition == null) {
152	      return Float.MAX_VALUE;
153	    }
154	    return Utils.SECOND_IN_NANOS / composition.getFrameRate() / Math.abs(speed);
155	  }
156	
157	  public void clearComposition() {
158	    this.composition = null;
159	    minFrame = Integer.MIN_VALUE;
160	    maxFrame = Integer.MAX_VALUE;
161	  }
162	
163	  public void setComposition(LottieComposition composition) {
164	    // Because the initial composition is loaded async, the first min/max frame may be set
165	    boolean keepMinAndMaxFrames = this.composition == null;
166	    this.composition = composition;
167	
168	    if (keepMinAndMaxFrames) {
169	      setMinAndMaxFrames(
170	          Math.max(this.minFrame, composition.getStartFrame()),
171	          Math.min(this.maxFrame, composition.getEndFrame())
172	      );
173	    } else {
174	      setMinAndMaxFrames((int) composition.getStartFrame(), (int) composition.getEndFrame());
175	    }
176	    float frame = this.frame;
177	    this.frame = 0f;
178	    this.frameRaw = 0f;
179	    setFrame((int) frame);
180	    notifyUpdate();
181	  }
182	
183	  public void setFrame(float frame) {
184	    if (this.frameRaw == frame) {
185	      return;
186	    }
187	    this.frameRaw = MiscUtils.clamp(frame, getMinFrame(), getMaxFrame());
188	    this.frame = useCompositionFrameRate ? ((float) Math.floor(frameRaw)) : frameRaw;
189	    lastFrameTimeNs = 0;
190	    notifyUpdate();
191	  }
192	
193	  public void setMinFrame(int minFrame) {
194	    setMinAndMaxFrames(minFrame, (int) maxFrame);
195	  }
196	
197	  public void setMaxFrame(float maxFrame) {
198	    setMinAndMaxFrames(minFrame, maxFrame);
199	  }
200	
201	  public void setMinAndMaxFrames(float minFrame, float maxFrame) {
202	    if (minFrame > maxFrame) {
203	      throw new IllegalArgumentException(String.format("minFrame (%s) must be <= maxFrame (%s)", minFrame, maxFrame));
204	    }
205	    float compositionMinFrame = composition == null ? -Float.MAX_VALUE : composition.getStartFrame();
206	    float compositionMaxFrame = composition == null ? Float.MAX_VALUE : composition.getEndFrame();
207	    float newMinFrame = MiscUtils.clamp(minFrame, compositionMinFrame, compositionMaxFrame);
208	    float newMaxFrame = MiscUtils.clamp(maxFrame, compositionMinFrame, compositionMaxFrame);
209	    if (newMinFrame != this.minFrame || newMaxFrame != this.maxFrame) {
210	      this.minFrame = newMinFrame;
211	      this.maxFrame = newMaxFrame;
212	      setFrame((int) MiscUtils.clamp(frame, newMinFrame, newMaxFrame));
213	    }
214	  }
215	
216	  public void reverseAnimationSpeed() {
217	    setSpeed(-getSpeed());
218	  }
219	
220	  public void setSpeed(float speed) {
221	    this.speed = speed;
222	  }
223	
224	  /**
225	   * Returns the current speed. This will be affected by repeat mode REVERSE.
226	   */
227	  public float getSpeed() {
228	    return speed;
229	  }
230	
231	  @Override public void setRepeatMode(int value) {
232	    super.setRepeatMode(value);
233	    if (value != REVERSE && speedReversedForRepeatMode) {
234	      speedReversedForRepeatMode = false;
235	      reverseAnimationSpeed();
236	    }
237	  }
238	
239	  @MainThread
240	  public void playAnimation() {
241	    running = true;
242	    notifyStart(isReversed());
243	    setFrame((int) (isReversed() ? getMaxFrame() : getMinFrame()));
244	    lastFrameTimeNs = 0;
245	    repeatCount = 0;
246	    postFrameCallback();
247	  }
248	
249	  @MainThread
250	  public void endAnimation() {
251	    removeFrameCallback();
252	    notifyEnd(isReversed());
253	  }
254	
255	  @MainThread
256	  public void pauseAnimation() {
257	    removeFrameCallback();
258	    notifyPause();
259	  }
260	
261	  @MainThread
262	  public void resumeAnimation() {
263	    running = true;
264	    postFrameCallback();
265	    lastFrameTimeNs = 0;
266	    if (isReversed() && getFrame() == getMinFrame()) {
267	      setFrame(getMaxFrame());
268	    } else if (!isReversed() && getFrame() == getMaxFrame()) {
269	      setFrame(getMinFrame());
270	    }
271	    notifyResume();
272	  }
273	
274	  @MainThread
275	  @Override public void cancel() {
276	    notifyCancel();
277	    removeFrameCallback();
278	  }
279	
280	  private boolean isReversed() {
281	    return getSpeed() < 0;
282	  }
283	
284	  public float getMinFrame() {
285	    if (composition == null) {
286	      return 0;
287	    }
288	    return minFrame == Integer.MIN_VALUE ? composition.getStartFrame() : minFrame;
289	  }
290	
291	  public float getMaxFrame() {
292	    if (composition == null) {
293	      return 0;
294	    }
295	    return maxFrame == Integer.MAX_VALUE ? composition.getEndFrame() : maxFrame;
296	  }
297	
298	  @Override void notifyCancel() {
299	    super.notifyCancel();
300	    notifyEnd(isReversed());
301	  }
302	
303	  protected void postFrameCallback() {
304	    if (isRunning()) {
305	      removeFrameCallback(false);
306	      Choreographer.getInstance().postFrameCallback(this);
307	    }
308	  }
309	
310	  @MainThread
311	  protected void removeFrameCallback() {
312	    this.removeFrameCallback(true);
313	  }
314	
315	  @MainThread
316	  protected void removeFrameCallback(boolean stopRunning) {
317	    Choreographer.getInstance().removeFrameCallback(this);
318	    if (stopRunning) {
319	      running = false;
320	    }
321	  }
322	
323	  private void verifyFrame() {
324	    if (composition == null) {
325	      return;
326	    }
327	    if (frame < minFrame || frame > maxFrame) {
328	      throw new IllegalStateException(String.format("Frame must be [%f,%f]. It is %f", minFrame, maxFrame, frame));
329	    }
330	  }
331	}
