1	package com.airbnb.lottie.parser;
2	
3	import com.airbnb.lottie.LottieComposition;
4	import com.airbnb.lottie.animation.keyframe.PathKeyframe;
5	import com.airbnb.lottie.parser.moshi.JsonReader;
6	import com.airbnb.lottie.value.Keyframe;
7	
8	import java.io.IOException;
9	import java.util.ArrayList;
10	import java.util.List;
11	
12	class KeyframesParser {
13	
14	  static JsonReader.Options NAMES = JsonReader.Options.of("k");
15	
16	  private KeyframesParser() {
17	  }
18	
19	  static <T> List<Keyframe<T>> parse(JsonReader reader, LottieComposition composition,
20	      float scale, ValueParser<T> valueParser, boolean multiDimensional) throws IOException {
21	    List<Keyframe<T>> keyframes = new ArrayList<>();
22	
23	    if (reader.peek() == JsonReader.Token.STRING) {
24	      composition.addWarning("Lottie doesn't support expressions.");
25	      return keyframes;
26	    }
27	
28	    reader.beginObject();
29	    while (reader.hasNext()) {
30	      switch (reader.selectName(NAMES)) {
31	        case 0:
32	          if (reader.peek() == JsonReader.Token.BEGIN_ARRAY) {
33	            reader.beginArray();
34	
35	            if (reader.peek() == JsonReader.Token.NUMBER) {
36	              // For properties in which the static value is an array of numbers.
37	              keyframes.add(KeyframeParser.parse(reader, composition, scale, valueParser, false, multiDimensional));
38	            } else {
39	              while (reader.hasNext()) {
40	                keyframes.add(KeyframeParser.parse(reader, composition, scale, valueParser, true, multiDimensional));
41	              }
42	            }
43	            reader.endArray();
44	          } else {
45	            keyframes.add(KeyframeParser.parse(reader, composition, scale, valueParser, false, multiDimensional));
46	          }
47	          break;
48	        default:
49	          reader.skipValue();
50	      }
51	    }
52	    reader.endObject();
53	
54	    setEndFrames(keyframes);
55	    return keyframes;
56	  }
57	
58	  /**
59	   * The json doesn't include end frames. The data can be taken from the start frame of the next
60	   * keyframe though.
61	   */
62	  public static <T> void setEndFrames(List<? extends Keyframe<T>> keyframes) {
63	    int size = keyframes.size();
64	    for (int i = 0; i < size - 1; i++) {
65	      // In the json, the keyframes only contain their starting frame.
66	      Keyframe<T> keyframe = keyframes.get(i);
67	      Keyframe<T> nextKeyframe = keyframes.get(i + 1);
68	      keyframe.endFrame = nextKeyframe.startFrame;
69	      if (keyframe.endValue == null && nextKeyframe.startValue != null) {
70	        keyframe.endValue = nextKeyframe.startValue;
71	        if (keyframe instanceof PathKeyframe) {
72	          ((PathKeyframe) keyframe).createPath();
73	        }
74	      }
75	    }
76	    Keyframe<?> lastKeyframe = keyframes.get(size - 1);
77	    if ((lastKeyframe.startValue == null || lastKeyframe.endValue == null) && keyframes.size() > 1) {
78	      // The only purpose the last keyframe has is to provide the end frame of the previous
79	      // keyframe.
80	      keyframes.remove(lastKeyframe);
81	    }
82	  }
83	}
