123	  /**
124	   * For a given key and depth, returns how much the depth should be incremented by when
125	   * resolving a keypath to children.
126	   * <p>
127	   * This can be 0 or 2 when there is a globstar and the next key either matches or doesn't match
128	   * the current key.
129	   */
130	  @RestrictTo(RestrictTo.Scope.LIBRARY)
131	  public int incrementDepthBy(String key, int depth) {
132	    if (isContainer(key)) {
133	      // If it's a container then we added programatically and it isn't a part of the keypath.
134	      return 0;
135	    }
136	    if (!keys.get(depth).equals("**")) {
137	      // If it's not a globstar then it is part of the keypath.
138	      return 1;
139	    }
140	    if (depth == keys.size() - 1) {
141	      // The last key is a globstar.
142	      return 0;
143	    }
144	    if (keys.get(depth + 1).equals(key)) {
145	      // We are a globstar and the next key is our current key so consume both.
146	      return 2;
